import React,{useState,useEffect,useRef,createContext,useContext} from 'react';
import { LayoutDashboard, Banknote, Wallet, ReceiptText, RefreshCw, Scale, BookOpen, ChartNoAxesCombined, Settings2, Shapes, ChevronDown, ChevronRight, ChevronLeft, Plus, Search, Bell, HelpCircle, ArrowUpRight, ArrowDownLeft, ArrowLeft, ArrowRight, Download, SlidersHorizontal, CalendarDays, Check, X, CheckCheck, CircleCheck, CircleAlert, Clock3, MoreHorizontal, Paperclip, Trash2, FileText, Send, Menu, Building2, Users, ShieldCheck, ExternalLink, Info, RotateCcw, Eye, Landmark, CircleDollarSign } from 'lucide-react';
