const Ctx=createContext();const useApp=()=>useContext(Ctx);
const modules={dashboard:{label:'Overview',icon:LayoutDashboard},'cash-requests':{label:'Cash requests',singular:'Cash Request',type:'requests',icon:Banknote},reimbursements:{label:'Expense Settlements',singular:'Reimbursement',type:'reimbursements',icon:ReceiptText},liquidations:{label:'Expense Settlements',singular:'Liquidation',type:'liquidations',icon:ReceiptText},replenishments:{label:'Replenishments',singular:'Replenishment',type:'replenishments',icon:RefreshCw},reconciliations:{label:'Reconciliation',singular:'Reconciliation',type:'counts',icon:Scale},ledger:{label:'Transaction ledger',icon:BookOpen},reports:{label:'Reports & insights',icon:ChartNoAxesCombined},funds:{label:'Petty cash funds',singular:'Petty Cash Fund',type:'funds',icon:Wallet},categories:{label:'Expense categories',singular:'Expense Category',type:'categories',icon:Shapes},policies:{label:'Policies & guide',icon:ShieldCheck}};
const names={requester:'Requester',approver:'Approver',custodian:'Custodian',finance:'Finance / Admin',superuser:'Super User'};
const blankItem=()=>({id:crypto.randomUUID(),category:'',description:'',value:'',payee:'',date:TODAY});
function Btn({children,icon:Icon,variant='',className='',...props}){return <button className={`btn ${variant} ${className}`} {...props}>{Icon&&<Icon size={16}/>} {children}</button>}
function IconButton({icon:Icon,label,...props}){return <button className="icon-btn" aria-label={label} title={label} {...props}><Icon size={18}/></button>}
function Pill({status}){let color=['Approved','Active','Liquidated','Verified','Reconciled'].includes(status)?'green':['Posted','Closed','Released','Paid'].includes(status)?'blue':['Needs Correction','Needs Changes','Overdue','Reimbursement Required'].includes(status)?'amber':['Rejected','Shortage','Overage'].includes(status)?'red':['Draft','Inactive','Cancelled'].includes(status)?'gray':'purple';return <span className={`pill ${color}`}><i/>{status}</span>}
function Avatar({name,size='small'}){return <span className={`avatar ${size} av-${(name||'').length%4}`}>{(name||'?').split(' ').map(x=>x[0]).slice(0,2).join('')}</span>}
function Field({label,required,children,hint,className=''}){return <label className={`field ${className}`}><span>{label}{required&&<b> *</b>}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Notice({children,type='info'}){const Icon=type==='error'?CircleAlert:type==='success'?CircleCheck:Info;return <div className={`notice ${type}`}><Icon size={17}/><div>{children}</div></div>}
function Empty({title='No records found',text='Try changing your search or filters.',action}){return <div className="empty"><span className="empty-icon"><FileText size={25}/></span><h3>{title}</h3><p>{text}</p>{action}</div>}
function Section({title,description,children,action,className=''}){return <section className={`panel ${className}`}><div className="section-head"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div>{children}</section>}
function Modal({title,description,children,onClose,wide=false,confirmation=false}){const ref=useRef();useEffect(()=>{const el=ref.current;const before=document.activeElement;el.showModal();return()=>{el.close();before?.focus?.()}},[]);return <dialog ref={ref} className={[wide?'wide':'',confirmation?'confirmation-modal':''].filter(Boolean).join(' ')} aria-label={title} onCancel={e=>{e.preventDefault();onClose()}} onClick={e=>{if(e.target===ref.current)onClose()}}><>{confirmation?<div className="confirmation-close"><IconButton icon={X} label="Close dialog" onClick={onClose}/></div>:<div className="modal-head"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div><IconButton icon={X} label="Close dialog" onClick={onClose}/></div>}</>{children}</dialog>}
function Confirm({config,onClose}){const [note,setNote]=useState(''),[reference,setReference]=useState(''),[checked,setChecked]=useState(false),[source,setSource]=useState('Outside petty cash'),[error,setError]=useState('');return <Modal title={config.title} onClose={onClose} confirmation><div className="modal-body"><div className="confirmation-intro"><div className={`confirm-icon ${config.danger?'danger':''}`}><config.icon size={25}/></div><h2>{config.title}</h2><p className="confirm-copy">{config.message}</p></div>{config.reason&&<Field label="Reason / feedback" required><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Explain the decision so the next person knows what to do…" rows={3}/></Field>}{config.payment&&<Field label="Payment source"><select value={source} onChange={e=>setSource(e.target.value)}><option>Outside petty cash</option><option>Petty cash fund</option></select></Field>}{config.receipt&&<><Field label={config.referenceLabel||'Voucher / receipt reference'} required><input value={reference} onChange={e=>setReference(e.target.value)} placeholder="e.g. RCV-2026-014"/></Field><label className="check-box"><input type="checkbox" checked={checked} onChange={e=>setChecked(e.target.checked)}/><span>{config.receipt}</span></label></>}{error&&<Notice type="error">{error}</Notice>}</div><div className="modal-footer"><Btn onClick={onClose}>Cancel</Btn><Btn variant={config.danger?'danger':'primary'} onClick={()=>{if(config.reason&&!note.trim())return setError('Please enter a reason.');if(config.receipt&&(!checked||!reference.trim()))return setError('Enter a reference and confirm the actual handover or receipt.');const ok=config.onConfirm({note,reference,confirmed:checked,source});if(ok!==false)onClose();else setError('The action could not be completed. Check the notification for details.')}}>{config.action||'Confirm'}</Btn></div></Modal>}
function DataTable({columns,rows,onRow,empty,initialSize=6}){const [page,setPage]=useState(1),[size,setSize]=useState(initialSize),[sort,setSort]=useState(null);useEffect(()=>setPage(1),[rows.length,size]);let ordered=[...rows];if(sort)ordered.sort((a,b)=>{const av=sort.column.value?.(a)??a[sort.column.key]??'',bv=sort.column.value?.(b)??b[sort.column.key]??'';return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv)))*(sort.asc?1:-1)});let pages=Math.max(1,Math.ceil(ordered.length/size)),current=Math.min(page,pages),shown=ordered.slice((current-1)*size,current*size);return <><div className="table-scroll"><table><thead><tr>{columns.map((c,i)=><th key={c.key||i} className={c.align==='right'?'align-right':''}>{c.sortable===false?c.label:<button className="sort" onClick={()=>setSort({column:c,asc:sort?.column===c?!sort.asc:true})}>{c.label}<ChevronDown size={12}/></button>}</th>)}</tr></thead><tbody>{shown.map((r,i)=><tr key={r.id||i} className={onRow?'clickable':''}>{columns.map((c,j)=><td key={c.key||j} className={c.align==='right'?'align-right':''}>{c.render?c.render(r):r[c.key]}</td>)}</tr>)}</tbody></table>{!rows.length&&(empty||<Empty/>)}</div><div className="table-footer"><span>Showing <strong>{rows.length?(current-1)*size+1:0}–{Math.min(current*size,rows.length)}</strong> of <strong>{rows.length}</strong> records</span><div className="pagination"><label>Rows <select aria-label="Rows per page" value={size} onChange={e=>setSize(Number(e.target.value))}>{[6,10,25].map(x=><option key={x}>{x}</option>)}</select></label><IconButton icon={ChevronLeft} label="Previous page" disabled={current===1} onClick={()=>setPage(current-1)}/>{Array.from({length:pages},(_,i)=><button key={i} className={current===i+1?'selected':''} aria-label={`Page ${i+1}`} aria-current={current===i+1?'page':undefined} onClick={()=>setPage(i+1)}>{i+1}</button>)}<IconButton icon={ChevronRight} label="Next page" disabled={current===pages} onClick={()=>setPage(current+1)}/></div></div></>}
function useLink(module){const {navigate}=useApp();return (id,label)=> <button className="text-link" onClick={()=>navigate(`/${module}/${id}`)}>{label||id}</button>}
function PageHeading({title,description,children,back,eyebrow}){const {navigate}=useApp();return <div className={`page-heading ${back?'transaction-heading':''}`}><div>{back&&<button className="back" onClick={()=>navigate(back.path)}><ArrowLeft size={14}/>{back.label}</button>}{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1>{description&&<p>{description}</p>}</div><div className="heading-actions">{children}</div></div>}
function History({record}){return <aside className="activity panel"><h2>Activity history</h2><p className="muted">All times in Asia/Manila</p><div className="timeline">{[...(record.history||[])].reverse().map((e,i)=><div className="event" key={i}><i/><div><strong>{e.action}</strong><p>{e.actor}</p>{e.note&&<blockquote>{e.note}</blockquote>}<time>{new Date(e.time).toLocaleString('en-PH',{timeZone:'Asia/Manila',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</time></div></div>)}</div><div className="history-foot"><ShieldCheck size={15}/> {record.fixture?'Sample record':'Created this session'}</div></aside>}
function Summary({entries}){return <dl className="summary-grid">{entries.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value||'—'}</dd></div>)}</dl>}
function AmountSummary({release,actual,returned=0,returnConfirmed=false,compact=false}){const due=Math.max(0,actual-release),expected=Math.max(0,release-actual),difference=Math.max(0,release-actual-returned);return <div className={`amount-summary ${compact?'compact':''}`}><h3>Financial summary</h3><dl><div><dt>Release amount</dt><dd>{money(release)}</dd></div><div><dt>Total actual expenses</dt><dd>{money(actual)}</dd></div><div><dt>Returned cash {returnConfirmed&&<Check size={13}/>}</dt><dd>{money(returned)}</dd></div><div><dt>Reimbursement due</dt><dd className={due?'warning-text':''}>{money(due)}</dd></div><div className="total"><dt>Unaccounted amount</dt><dd>{money(difference)}</dd></div></dl><div className={`accounted ${difference||returned!==expected?'warn':due?'warn':'ok'}`}>{difference||returned!==expected?<><CircleAlert size={15}/> Resolve the cash difference</>:due?<><CircleAlert size={15}/> Reimbursement required</>:<><CircleCheck size={15}/> Fully accounted</>}</div></div>}

export default function App(){
  const [db,setDb]=useState(initialData),[role,setRole]=useState('custodian'),[route,setRoute]=useState(location.hash.slice(1)||'/dashboard'),[modal,setModal]=useState(null),[toast,setToast]=useState(null),[dirty,setDirty]=useState(false),[sidebar,setSidebar]=useState(false),[query,setQuery]=useState('');
  const stateRef=useRef(db);stateRef.current=db;const [module='dashboard',id,edit]=route.split('?')[0].slice(1).split('/');
  const notify=(message,type='success')=>setToast({message,type});
  const go=path=>{location.hash=path;setRoute(path);setDirty(false);setSidebar(false);setQuery('');window.scrollTo(0,0)};
  const navigate=path=>{if(path===route)return;if(dirty)setModal({kind:'confirm',icon:CircleAlert,title:'Discard unsaved changes?',message:'Your changes have not been saved. Leave this page and discard them?',action:'Discard changes',danger:true,onConfirm:()=>go(path)});else go(path)};
  useEffect(()=>{const onHash=()=>{const next=location.hash.slice(1)||'/dashboard';if(dirty&&next!==route){history.replaceState(null,'','#'+route);navigate(next)}else{setRoute(next);window.scrollTo(0,0)}};const unload=e=>{if(dirty){e.preventDefault();e.returnValue=''}};window.addEventListener('hashchange',onHash);window.addEventListener('beforeunload',unload);return()=>{window.removeEventListener('hashchange',onHash);window.removeEventListener('beforeunload',unload)}},[dirty,route]);
  useEffect(()=>{document.title=`${modules[module]?.label||'Petty Cash'} · Petty Cash`},[module]);useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(null),6000);return()=>clearTimeout(t)}},[toast]);
  const commit=(action,message,path)=>{try{const result=transact(stateRef.current,action,role);stateRef.current=result.db;setDb(result.db);if(message)notify(message);if(path){setDirty(false);go(typeof path==='function'?path(result):path)}return true}catch(e){notify(e.message,'error');return false}};
  const confirm=(config)=>setModal({kind:'confirm',icon:CircleCheck,...config});
  const changeRole=r=>{const act=()=>{setRole(r);go('/dashboard');notify(`Now viewing as ${roles[r].label}.`)};if(dirty)confirm({icon:Users,title:'Switch roles and discard changes?',message:'This form has unsaved changes. Switching roles will discard them.',action:'Switch role',onConfirm:act});else act()};
  const available=Object.keys(modules).filter(m=>!(['funds','categories'].includes(m)&&!can(role,'manage'))&&!(['ledger','reports'].includes(m)&&!can(role,'reports'))&&!(['replenishments','reconciliations'].includes(m)&&!can(role,'reports')));
  const rolePending=role==='requester'?db.requests.filter(r=>r.owner===roles[role].name&&r.status==='Needs Changes').map(r=>({module:'cash-requests',record:r,text:'Update your cash request'})).concat(db.liquidations.filter(l=>l.owner===roles[role].name&&l.status==='Needs Correction').map(l=>({module:'liquidations',record:l,text:'Correct your liquidation'}))):role==='approver'?db.requests.filter(r=>r.status==='Pending Approval').map(r=>({module:'cash-requests',record:r,text:'Cash request awaiting your decision'})):role==='custodian'?db.requests.filter(r=>r.status==='Approved').map(r=>({module:'cash-requests',record:r,text:'Approved cash ready for release'})).concat(db.liquidations.filter(l=>l.status==='Submitted').map(l=>({module:'liquidations',record:l,text:'Liquidation ready for verification'}))):[...db.replenishments.filter(r=>['Pending Approval','Approved'].includes(r.status)).map(r=>({module:'replenishments',record:r,text:r.status==='Approved'?'Record replenishment funding receipt':'Review replenishment'})),...db.counts.filter(r=>r.status==='Pending Approval').map(r=>({module:'reconciliations',record:r,text:'Review cash reconciliation'})),...db.funds.filter(r=>r.status==='Pending Approval').map(r=>({module:'funds',record:r,text:'Review fund authorization'})),...db.liquidations.filter(l=>l.status==='Verified'&&l.excess).map(l=>({module:'liquidations',record:l,text:'Reimbursement needs Finance review'}))];
  const advancePending=can(role,'editAll')?[...rolePending,...db.requests.filter(r=>['Pending Approval','Approved','Needs Changes'].includes(r.status)).map(r=>({module:'cash-requests',record:r,text:r.status==='Approved'?'Cash ready for release':r.status==='Needs Changes'?'Cash request needs changes':'Cash request awaiting review'})),...db.liquidations.filter(l=>['Submitted','Needs Correction'].includes(l.status)).map(l=>({module:'liquidations',record:l,text:l.status==='Submitted'?'Liquidation ready for verification':'Liquidation needs correction'}))]:rolePending;
  const reimbursementPending=db.reimbursements.filter(r=>role==='requester'?r.owner===roles[role].name&&r.status==='Needs Correction':can(role,'approveRequest')&&r.status==='Pending Approval'||can(role,'reimburse')&&r.status==='Approved — Pending Payment').map(r=>({module:'reimbursements',record:r,text:r.status==='Approved — Pending Payment'?'Pay approved reimbursement':r.status==='Needs Correction'?'Correct your reimbursement':'Review reimbursement'}));
  const pending=[...advancePending,...reimbursementPending];
  const searchRecords=query.trim()?[...scopedRequests(db,role).map(r=>({...r,module:'cash-requests',label:r.purpose})),...db.reimbursements.filter(r=>role!=='requester'||r.owner===roles[role].name).map(r=>({...r,module:'reimbursements',label:r.purpose})),...db.liquidations.filter(r=>role!=='requester'||r.owner===roles[role].name).map(r=>({...r,module:'liquidations',label:r.request})),...(can(role,'reports')?db.funds.map(r=>({...r,module:'funds',label:r.name})):[])].filter(r=>`${r.id} ${r.label} ${r.owner||''}`.toLowerCase().includes(query.toLowerCase())).slice(0,7):[];
  const context={db,role,navigate,commit,confirm,notify,setDirty,setModal,pending};
  return <Ctx.Provider value={context}><a href="#main" className="skip-link" onClick={e=>{e.preventDefault();document.getElementById('main').focus()}}>Skip to content</a><div className="app-shell"><aside className={`sidebar ${sidebar?'open':''}`}><button className="brand" onClick={()=>navigate('/dashboard')}><span className="brand-icon"><Wallet size={22}/></span><span>petty<span className="brand-light">cash</span><small>Finance workspace</small></span></button><button className="workspace-switch" onClick={()=>setModal({kind:'company'})}><span className="company-icon"><Building2 size={18}/></span><span>Mayden Group<small>Company workspace</small></span><ChevronDown size={14}/></button><nav aria-label="Main"><div className="nav-label">Workspace</div>{['dashboard','cash-requests','liquidations','replenishments','reconciliations'].filter(m=>available.includes(m)).map(m=>{const Icon=modules[m].icon;const count=m==='cash-requests'?pending.filter(p=>p.module===m).length:m==='liquidations'?pending.filter(p=>['liquidations','reimbursements'].includes(p.module)).length:0;return <button key={m} className={`nav-item ${(m===module||m==='liquidations'&&module==='reimbursements')?'active':''}`} onClick={()=>navigate('/'+m)}><Icon size={19}/><span>{modules[m].label}</span>{count>0&&<b>{count}</b>}</button>})}{can(role,'reports')&&<><div className="nav-label">Insights</div>{['ledger','reports'].map(m=>{const Icon=modules[m].icon;return <button key={m} className={`nav-item ${(m===module||m==='liquidations'&&module==='reimbursements')?'active':''}`} onClick={()=>navigate('/'+m)}><Icon size={18}/>{modules[m].label}</button>})}</>}<div className="nav-label">Administration</div>{['funds','categories','policies'].filter(m=>available.includes(m)).map(m=>{const Icon=modules[m].icon;return <button key={m} className={`nav-item ${(m===module||m==='liquidations'&&module==='reimbursements')?'active':''}`} onClick={()=>navigate('/'+m)}><Icon size={18}/>{modules[m].label}</button>})}</nav><div className="sidebar-bottom"><div className="help-card"><span className="help-icon"><HelpCircle size={20}/></span><h3>A little guidance?</h3><p>Walk through the complete petty cash journey.</p><button onClick={()=>setModal({kind:'guide'})}>Explore the guide <ArrowUpRight size={15}/></button></div><button className="user-card" onClick={()=>setModal({kind:'profile'})}><Avatar name={roles[role].name}/><span><strong>{roles[role].name}</strong><small>{roles[role].title}</small></span><MoreHorizontal size={17}/></button></div></aside>{sidebar&&<button className="sidebar-backdrop" aria-label="Close navigation" onClick={()=>setSidebar(false)}/>}<div className="workspace"><header className="topbar"><div className="topbar-left"><IconButton icon={Menu} label="Open navigation" onClick={()=>setSidebar(!sidebar)}/><div className="breadcrumb">Workspace <ChevronRight size={13}/> <span>{modules[module]?.label||'Overview'}</span>{id&&<><ChevronRight size={13}/><span>{id==='new'?'Create':id}</span></>}</div></div><div className="topbar-actions"><div className="global-search"><Search size={16}/><input aria-label="Search all records" placeholder="Search anything…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<div className="search-results"><div className="search-results-head">Records in your preview scope</div>{searchRecords.length?searchRecords.map(r=><button key={r.id} onClick={()=>navigate(`/${r.module}/${r.id}`)}><FileText size={17}/><span><strong>{r.id}</strong><small>{r.label}</small></span><ChevronRight size={14}/></button>):<p>No matching records.</p>}</div>}</div><div className="top-divider"/><IconButton icon={HelpCircle} label="Open prototype guide" onClick={()=>setModal({kind:'guide'})}/><button className="notification-btn icon-btn" aria-label={`Notifications, ${pending.length} pending items`} onClick={()=>setModal({kind:'notifications'})}><Bell size={19}/>{pending.length>0&&<i/>}</button><Avatar name={roles[role].name}/></div></header><div className="preview-bar"><div><span className="demo-label"><span/>Interactive prototype</span><span className="preview-note">Sample data · resets on refresh</span></div><label className="role-switch"><Eye size={15}/><span>Viewing as</span><select aria-label="Preview role" value={role} onChange={e=>changeRole(e.target.value)}>{Object.entries(roles).map(([id,r])=><option key={id} value={id}>{r.label}</option>)}</select></label></div><main id="main" tabIndex={-1}>
    {!available.includes(module)?<Empty title="This area belongs to another role" text="Use the role preview above to explore the appropriate workspace." action={<Btn onClick={()=>navigate('/dashboard')}>Back to overview</Btn>}/>:module==='dashboard'?<Dashboard/>:module==='policies'?<Policies/>:module==='reports'?<Reports/>:module==='ledger'?<Ledger/>:module==='reimbursements'?(id==='new'||edit==='edit'?<ReimbursementForm key={`${route}-${role}`} id={edit==='edit'?id:null}/>:id?<ReimbursementDetail key={`${id}-${role}`} id={id}/>:<Settlements key={role}/>):module==='liquidations'&&!id?<Settlements key={role}/>:id==='new'||edit==='edit'?<TransactionForm key={`${route}-${role}`} module={module} id={edit==='edit'?id:null}/>:id?<Detail module={module} id={id}/>:<Listing key={`${module}-${role}`} module={module}/>}
  </main><footer className="app-footer"><span>© 2026 Mayden Group <span>·</span> Petty Cash Workspace</span><span><span className="live-dot"/> Session demo <button onClick={()=>confirm({icon:RotateCcw,title:'Reset the demo?',message:'This will discard all session changes and restore the original sample records.',action:'Reset demo',onConfirm:()=>{setDb(initialData());setDirty(false);go('/dashboard');notify('Sample data restored.')}})}>Reset demo</button></span></footer></div></div>
  {toast&&<div role={toast.type==='error'?'alert':'status'} className={`toast ${toast.type}`}>{toast.type==='error'?<CircleAlert size={19}/>:<CircleCheck size={19}/>}<span>{toast.message}</span><IconButton icon={X} label="Dismiss notification" onClick={()=>setToast(null)}/></div>}
  {modal?.kind==='confirm'&&<Confirm config={modal} onClose={()=>setModal(null)}/>}{modal?.kind==='guide'&&<Guide onClose={()=>setModal(null)} changeRole={changeRole}/>} {modal?.kind==='notifications'&&<Modal title="Your action center" description={`${pending.length} items need your attention`} onClose={()=>setModal(null)}><div className="notification-list">{pending.length?pending.map(p=><button key={p.record.id} onClick={()=>{setModal(null);navigate(`/${p.module}/${p.record.id}`)}}><span className="task-symbol"><Clock3 size={19}/></span><span><strong>{p.text}</strong><p>{p.record.id} · {p.record.owner||p.record.name}</p></span><ChevronRight size={17}/></button>):<Empty title="You're all caught up" text="There are no pending actions for this role."/>}</div></Modal>}{modal?.kind==='company'&&<Modal title="Mayden Group" description="Company workspace" onClose={()=>setModal(null)}><div className="modal-body"><Summary entries={[["Company","Mayden Cleaning Solutions, Inc."],["Location","Makati City, Philippines"],["Currency","PHP · Philippine peso"],["Business date",dateLabel(TODAY)]]}/><Notice>This is a fictional company workspace for exploring the prototype.</Notice></div></Modal>}{modal?.kind==='profile'&&<Modal title={roles[role].name} description={roles[role].title} onClose={()=>setModal(null)}><div className="modal-body"><p>This role can {roles[role].permissions.map(p=>({request:'create cash requests',liquidate:'submit own liquidations',approveRequest:'approve requests',release:'release cash',verify:'verify liquidations',replenish:'request replenishment',count:'count physical cash',reports:'view reports and ledger',manage:'manage funds and categories',approveCount:'review reconciliations',approveReplenishment:'approve and post replenishments',reimburse:'record reimbursement payments',editAll:'edit all users’ transactions and review own submissions'}[p])).join(', ')}.</p><Notice>Role preview simulates permissions within this browser session.</Notice></div></Modal>}{modal?.kind==='movement'&&<Modal title={'Opening funding · '+db.funds.find(f=>f.id===modal.record.fund)?.name} onClose={()=>setModal(null)}><SourceMovement record={modal.record} funds={db.funds}/></Modal>}{modal?.kind==='category'&&<CategoryModal record={modal.record} onClose={()=>setModal(null)}/>}
  </Ctx.Provider>
}

function Dashboard(){const {db,role,navigate,pending}=useApp();const [fund,setFund]=useState('all'),[range,setRange]=useState('month');const rs=scopedRequests(db,role).filter(r=>fund==='all'||r.fund===fund);const fs=db.funds.filter(f=>f.status==='Active'&&(fund==='all'||f.id===fund));const cash=fs.reduce((n,f)=>n+balance(db,f.id),0),authorized=fs.reduce((n,f)=>n+f.authorized,0);const outstanding=rs.filter(r=>r.status==='Released'),awaiting=rs.filter(r=>r.status==='Pending Approval');const lqs=[...db.liquidations,...db.reimbursements].filter(l=>(role!=='requester'||l.owner===roles[role].name)&&(fund==='all'||l.fund===fund));const start=range==='week'?'2026-10-15':'2026-10-01';const verified=lqs.filter(l=>['Verified','Liquidated','Approved — Pending Payment','Paid'].includes(l.status)&&l.date>=start);const spent=verified.reduce((n,l)=>n+sum(l.items),0);const overdue=outstanding.filter(r=>r.due<TODAY);const fundsLabel=fund==='all'?'Across all active funds':db.funds.find(f=>f.id===fund)?.name;const primary=can(role,'request')?['New cash request','/cash-requests/new']:can(role,'replenish')?['New replenishment','/replenishments/new']:can(role,'manage')?['Manage funds','/funds']:['Review requests','/cash-requests'];
return <><PageHeading title={role==='requester'?'Your cash, all accounted for.':'A clear view of your petty cash.'} description={`Welcome back, ${roles[role].name.split(' ')[0]}. Here’s what’s happening ${range==='week'?'this week':'this month'}.`}><div className="date-chip"><CalendarDays size={16}/>{dateLabel(TODAY)}</div><>{can(role,'request')&&<Btn icon={ReceiptText} onClick={()=>navigate('/reimbursements/new')}>Claim personal expenses</Btn>}</><Btn variant="primary" icon={Plus} onClick={()=>navigate(primary[1])}>{primary[0]}</Btn></PageHeading><div className="dashboard-toolbar"><div className="segmented"><button className={range==='month'?'active':''} onClick={()=>setRange('month')}>This month</button><button className={range==='week'?'active':''} onClick={()=>setRange('week')}>Last 7 days</button></div><select aria-label="Dashboard fund" value={fund} onChange={e=>setFund(e.target.value)}><option value="all">All petty cash funds</option>{db.funds.filter(f=>f.status==='Active').map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></div>
<div className="stats-grid"><div className="stat-card cash-stat"><div className="stat-top"><span>Available cash balance</span><span className="stat-icon"><Wallet size={19}/></span></div><div className="stat-value">{money(cash)}</div><div className="cash-meter"><span style={{width:`${Math.min(100,cash/authorized*100)}%`}}/></div><div className="stat-foot"><span>{Math.round(cash/authorized*100)}% of authorized fund</span><span>{money(authorized)}</span></div><small>{fundsLabel} · as of {dateLabel(TODAY)}</small></div><Stat label="Outstanding advances" value={money(outstanding.reduce((n,r)=>n+r.amount,0))} icon={ArrowUpRight} color="blue" foot={`${outstanding.length} released requests to liquidate`} action={()=>navigate('/cash-requests')}/><Stat label="Approved / verified expenses" value={money(spent)} icon={ReceiptText} color="purple" foot={`${verified.length} approved / verified settlements`} action={()=>navigate(can(role,'reports')?'/reports':'/liquidations')}/><Stat label="Needs your attention" value={String(pending.length).padStart(2,'0')} icon={Clock3} color="orange" foot={overdue.length?`${overdue.length} overdue advances in scope`:'Your next actions, in one place'} action={()=>document.querySelector('[aria-label^="Notifications"]')?.click()}/></div>
<div className="dashboard-middle"><Section title="Cash movement" description="Money in and out of your funds" action={<div className="chart-legend"><span><i className="cash-in-key"/>Cash in</span><span><i className="cash-out-key"/>Cash out</span></div>}><CashChart db={db} fund={fund} start={start}/></Section><Section title="Your action center" action={<span className="count-badge">{pending.length}</span>} className="action-center">{pending.length?<div className="task-list">{pending.slice(0,3).map((p,i)=><button onClick={()=>navigate(`/${p.module}/${p.record.id}`)} key={p.record.id}><span className={`task-icon tone-${i}`}>{p.module==='liquidations'?<ReceiptText size={20}/>:p.module==='funds'?<Wallet size={20}/>:<Banknote size={20}/>}</span><div><strong>{p.text}</strong><p>{p.record.id}</p><small>{p.record.owner||p.record.name}</small></div><ChevronRight size={16}/></button>)}</div>:<Empty title="All caught up" text="No decisions or corrections are waiting."/>}<button className="panel-bottom-link" onClick={()=>document.querySelector('[aria-label^="Notifications"]')?.click()}>View all pending actions <ArrowRight size={15}/></button></Section></div>
<div className="dashboard-bottom"><Section title="Recent cash requests" description="Keep an eye on requests from start to settlement" action={<button className="text-link" onClick={()=>navigate('/cash-requests')}>View all <ArrowUpRight size={14}/></button>}><DataTable rows={[...rs].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5)} initialSize={6} columns={[{key:'id',label:'Request',render:r=><div className="request-cell"><button className="text-link" onClick={()=>navigate('/cash-requests/'+r.id)}>{r.id}</button><small>{r.purpose}</small></div>},{key:'owner',label:'Requester',render:r=><div className="person"><Avatar name={r.owner}/><span>{r.owner}</span></div>},{key:'amount',label:'Amount',align:'right',render:r=><strong className="numeric">{money(r.amount)}</strong>},{key:'status',label:'Status',render:r=><Pill status={r.status}/>}]} /></Section><Section title="Expense breakdown" description="Verified liquidations and approved claims" className="breakdown"><CategoryChart items={verified.flatMap(l=>l.items)}/></Section></div>
{can(role,'reports')&&<Section title="Your petty cash funds" action={<button className="text-link" onClick={()=>navigate(can(role,'manage')?'/funds':'/ledger')}>{can(role,'manage')?'Manage funds':'View fund ledger'}<ArrowUpRight size={14}/></button>} className="fund-strip"><div className="fund-strip-grid">{fs.map(f=><button key={f.id} onClick={()=>{can(role,'manage')?navigate('/funds/'+f.id):navigate('/ledger?fund='+f.id)}}><span className="fund-mini-icon"><Building2 size={19}/></span><span><strong>{f.name}</strong><small>{f.code}</small></span><div><b>{money(balance(db,f.id))}</b><small>of {money(f.authorized)}</small></div><ChevronRight size={16}/></button>)}</div></Section>}</>}
function Stat({label,value,icon:Icon,color,foot,action}){return <button className="stat-card secondary-stat" onClick={action}><div className="stat-top"><span>{label}</span><span className={`stat-icon ${color}`}><Icon size={19}/></span></div><div className="stat-value">{value}</div><div className="stat-foot"><span>{foot}</span><ArrowUpRight size={15}/></div></button>}
function CashChart({db,fund,start}){const days=start==='2026-10-15'?[15,16,17,18,19,20,21]:[1,4,7,10,13,16,19,21];const bins=days.map((d,i)=>{const rows=db.movements.filter(m=>(fund==='all'||m.fund===fund)&&Number(m.date.slice(-2))>=d&&Number(m.date.slice(-2))<(days[i+1]||22));return {label:`Oct ${d}`,in:rows.filter(m=>m.amount>0).reduce((s,m)=>s+m.amount,0),out:rows.filter(m=>m.amount<0).reduce((s,m)=>s-m.amount,0)}});const max=Math.max(1000000,...bins.flatMap(x=>[x.in,x.out]));return <div className="cash-chart"><svg viewBox="0 0 680 222" role="img" aria-label="Cash-in and cash-out by date, in Philippine pesos">{[0,1,2,3].map(i=><g key={i}><line x1="50" x2="666" y1={23+i*49} y2={23+i*49} stroke="var(--border)" strokeDasharray="3 4"/><text x="38" y={27+i*49} textAnchor="end">₱{Math.round(max/100*(3-i)/3/1000)}k</text></g>)}{bins.map((b,i)=>{const x=64+i*75;return <g key={b.label}><rect x={x} y={170-b.in/max*147} width="17" height={Math.max(2,b.in/max*147)} rx="4" fill="var(--chart-cash-in)"><title>{b.label}: cash in {money(b.in)}</title></rect><rect x={x+21} y={170-b.out/max*147} width="17" height={Math.max(2,b.out/max*147)} rx="4" fill="var(--chart-cash-out)"><title>{b.label}: cash out {money(b.out)}</title></rect><text x={x+18} y="197" textAnchor="middle">{b.label}</text></g>})}</svg><div className="chart-summary"><span><i className="mini-dot cash-in-key"/> Total cash in <strong>{money(bins.reduce((n,b)=>n+b.in,0))}</strong></span><span><i className="mini-dot cash-out-key"/> Total cash out <strong>{money(bins.reduce((n,b)=>n+b.out,0))}</strong></span></div></div>}
function CategoryChart({items}){const groups=Object.entries(items.reduce((o,i)=>(o[i.category]=(o[i.category]||0)+i.amount,o),{})).sort((a,b)=>b[1]-a[1]);const colors=['var(--chart-1)','var(--chart-2)','var(--chart-3)','var(--chart-4)','var(--chart-5)'];const total=sum(items);let offset=0;return total?<><div className="donut-wrap"><svg viewBox="0 0 180 180" aria-label={`Total actual expenses ${money(total)}`} role="img">{groups.map(([name,value],i)=>{const p=value/total*100;const el=<circle key={name} cx="90" cy="90" r="68" fill="none" stroke={colors[i%5]} strokeWidth="18" pathLength="100" strokeDasharray={`${p} ${100-p}`} strokeDashoffset={-offset} transform="rotate(-90 90 90)"><title>{name}: {money(value)}</title></circle>;offset+=p;return el})}</svg><div><small>Total expenses</small><strong>{money(total)}</strong></div></div><div className="category-legend">{groups.slice(0,5).map(([name,value],i)=><div key={name}><span><i style={{background:colors[i%5]}}/>{name}</span><strong>{Math.round(value/total*100)}%</strong></div>)}</div></>:<Empty title="No expenses in this period" text="Approved / verified expenses will appear here."/>}

function Listing({module}){const {db,role,navigate,setModal}=useApp();const cfg=modules[module];const [tab,setTab]=useState('all'),[query,setQuery]=useState(''),[status,setStatus]=useState('all'),[fund,setFund]=useState('all');const link=useLink(module);const review=module==='cash-requests'?can(role,'approveRequest'):module==='liquidations'?can(role,'verify'):module==='replenishments'?can(role,'approveReplenishment'):module==='reconciliations'?can(role,'approveCount'):module==='funds'?can(role,'manage'):false;
let base=db[cfg.type]||[];if(module==='cash-requests')base=scopedRequests(db,role);if(module==='liquidations'&&role==='requester')base=base.filter(r=>r.owner===roles[role].name);const pendingStatus=module==='liquidations'?'Submitted':'Pending Approval';const tabs=[['all',module==='liquidations'&&role==='requester'?'My Liquidations':module==='reconciliations'?'Reconciliations':cfg.label],...(review?[['review',module==='liquidations'?'For Verification':'For Approval']]:[]),...(module==='liquidations'&&role==='requester'?[['active','Active'],['completed','Completed']]:[])];const rows=base.filter(r=>(tab!=='review'||r.status===pendingStatus)&&(tab!=='active'||!['Liquidated'].includes(r.status))&&(tab!=='completed'||r.status==='Liquidated')&&(status==='all'||r.status===status)&&(fund==='all'||(module==='funds'?r.id:r.fund)===fund)&&`${r.id} ${r.name||''} ${r.purpose||''} ${r.owner||''} ${r.request||''} ${r.description||''}`.toLowerCase().includes(query.toLowerCase()));
const canCreate=module==='cash-requests'?can(role,'request'):module==='liquidations'?can(role,'liquidate'):module==='replenishments'?can(role,'replenish'):module==='reconciliations'?can(role,'count'):can(role,'manage');
const description={ 'cash-requests':'Request, review, and track advances for everyday business expenses.',liquidations:'Account for released cash with actual expenses and supporting receipts.',replenishments:'Restore your funds from verified, fully liquidated expenses.',reconciliations:'Compare physical cash with recorded balances and preserve every difference.',funds:'Manage fund authorizations, custodians, and operating limits.',categories:'Keep expense classifications organized and consistent.' }[module];
const columns=module==='cash-requests'?[{key:'id',label:'Cash Request No.',render:r=><div className="request-cell">{link(r.id)}<small>{dateLabel(r.date)}</small></div>},{key:'purpose',label:'Purpose',render:r=><div className="purpose-cell"><strong>{r.purpose}</strong><small>{db.funds.find(f=>f.id===r.fund)?.name}</small></div>},...(role!=='requester'?[{key:'owner',label:'Requester',render:r=><div className="person"><Avatar name={r.owner}/><span>{r.owner}<small>{r.department}</small></span></div>}]:[]),{key:'amount',label:'Requested amount',align:'right',render:r=><strong className="numeric">{money(r.amount)}</strong>},{key:'status',label:'Status',render:r=><><Pill status={r.status}/>{r.status==='Released'&&r.due<TODAY&&<small className="overdue">Overdue</small>}</>}]:module==='liquidations'?[{key:'id',label:'Settlement No.',render:r=>link(r.id)},{key:'request',label:'Cash Request No.',render:r=><button className="text-link muted-link" onClick={()=>navigate('/cash-requests/'+r.request)}>{r.request}</button>},{key:'date',label:'Liquidation date',render:r=>dateLabel(r.date)},...(role!=='requester'?[{key:'owner',label:'Requester',render:r=><div className="person"><Avatar name={r.owner}/>{r.owner}</div>}]:[]),{key:'release',label:'Release amount',align:'right',render:r=>money(r.release)},{key:'actual',label:'Actual expenses',value:r=>sum(r.items),align:'right',render:r=><strong className="numeric">{money(sum(r.items))}</strong>},...(tab==='review'?[{key:'returned',label:'Returned cash',align:'right',render:r=>money(r.returned)}]:[]),{key:'status',label:'Status',render:r=><><Pill status={r.status}/>{r.replenished&&<small className="muted">Replenished</small>}</>}]:module==='replenishments'?[{key:'id',label:'Replenishment No.',render:r=>link(r.id)},{key:'date',label:'Created date',render:r=>dateLabel(r.date)},{key:'fund',label:'Petty cash fund',render:r=>db.funds.find(f=>f.id===r.fund)?.name},{key:'owner',label:'Requested by'},{key:'liquidations',label:'Settlements',render:r=><span className="count-badge">{r.liquidations.length}</span>},{key:'amount',label:'Replenishment amount',align:'right',render:r=><strong className="numeric">{money(r.amount)}</strong>},{key:'status',label:'Status',render:r=><Pill status={r.status}/>}]:module==='reconciliations'?[{key:'id',label:'Reconciliation No.',render:r=>link(r.id)},{key:'date',label:'Count date',render:r=>dateLabel(r.date)},{key:'fund',label:'Fund',render:r=>db.funds.find(f=>f.id===r.fund)?.name},{key:'recorded',label:'Recorded cash',align:'right',render:r=>money(r.recorded)},{key:'physical',label:'Physical cash',align:'right',render:r=>money(r.physical)},{key:'variance',label:'Variance',align:'right',value:r=>r.physical-r.recorded,render:r=><strong className={r.physical!==r.recorded?'danger-text numeric':'success-text numeric'}>{money(r.physical-r.recorded)}</strong>},{key:'status',label:'Status',render:r=><Pill status={r.status}/>}]:module==='funds'?[{key:'name',label:'Petty cash fund',render:r=><div className="fund-cell"><span className="fund-mini-icon"><Wallet size={19}/></span><span>{link(r.id,r.name)}<small>{r.code} · {r.location}</small></span></div>},{key:'custodian',label:'Custodian',render:r=><div className="person"><Avatar name={r.custodian}/>{r.custodian}</div>},{key:'authorized',label:'Authorized amount',align:'right',render:r=>money(r.proposed?.authorized||r.authorized)},{key:'cash',label:'Recorded cash',value:r=>balance(db,r.id),align:'right',render:r=><strong className="numeric">{money(balance(db,r.id))}</strong>},{key:'status',label:'Status',render:r=><Pill status={r.status}/>}]:[{key:'name',label:'Category',render:r=><div className="category-name"><span className="category-icon"><Shapes size={17}/></span><strong>{r.name}</strong></div>},{key:'description',label:'Description'},{key:'status',label:'Status',render:r=><Pill status={r.status}/>}];
columns.push({key:'action',label:'Action',sortable:false,align:'right',render:r=>module==='categories'?<Btn variant="small" onClick={()=>setModal({kind:'category',record:r})}>Edit</Btn>:<button className="row-action" aria-label={`View ${r.id}`} onClick={()=>navigate(`/${module}/${r.id}`)}><ArrowUpRight size={17}/></button>});
return <><PageHeading title={cfg.label} description={description}>{can(role,'reports')&&<Btn icon={Download} onClick={()=>downloadCSV(rows,`${module}-2026-10-21.csv`)}>Export</Btn>}{canCreate&&<Btn variant="primary" icon={Plus} onClick={()=>module==='categories'?setModal({kind:'category'}):navigate('/'+module+'/new')}>New {module==='funds'?'Fund':module==='categories'?'Expense Category':cfg.singular}</Btn>}</PageHeading>
{module==='funds'&&<div className="mini-stats"><MiniStat label="Active funds" value={db.funds.filter(f=>f.status==='Active').length} icon={Wallet}/><MiniStat label="Total authorized" value={money(db.funds.filter(f=>f.status==='Active').reduce((n,f)=>n+f.authorized,0))} icon={Landmark}/><MiniStat label="Recorded cash" value={money(db.movements.reduce((n,m)=>n+m.amount,0))} icon={CircleDollarSign}/><MiniStat label="Awaiting approval" value={db.funds.filter(f=>f.status==='Pending Approval').length} icon={Clock3}/></div>}
{module==='liquidations'&&role==='requester'&&eligibleRequests(db,role).length>0&&<div className="action-banner"><span className="task-icon"><ReceiptText size={21}/></span><div><strong>{eligibleRequests(db,role).length} released advance{eligibleRequests(db,role).length>1?'s':''} ready for liquidation</strong><p>Start with your cash request. Estimated items will be copied for you.</p></div><Btn onClick={()=>navigate('/liquidations/new')}>Create Liquidation <ArrowRight size={15}/></Btn></div>}
<div className="panel listing-panel"><div className="tabs" role="tablist">{tabs.map(([id,label])=><button role="tab" aria-selected={tab===id} key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}<span>{id==='review'?base.filter(r=>r.status===pendingStatus).length:id==='active'?base.filter(r=>r.status!=='Liquidated').length:id==='completed'?base.filter(r=>r.status==='Liquidated').length:base.length}</span></button>)}</div><div className="table-toolbar"><div className="table-search"><Search size={16}/><input aria-label={`Search ${cfg.label}`} placeholder={`Search ${cfg.label.toLowerCase()}…`} value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="filter-controls"><div className="filter-select"><SlidersHorizontal size={15}/><select aria-label="Filter by status" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">All statuses</option>{[...new Set(base.map(r=>r.status))].map(s=><option key={s}>{s}</option>)}</select></div>{!['categories','funds'].includes(module)&&<select aria-label="Filter by fund" value={fund} onChange={e=>setFund(e.target.value)}><option value="all">All funds</option>{db.funds.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select>}{(query||status!=='all'||fund!=='all')&&<button className="text-link" onClick={()=>{setQuery('');setStatus('all');setFund('all')}}>Clear</button>}</div></div><DataTable columns={columns} rows={rows} onRow={r=>navigate('/'+module+'/'+r.id)}/></div><div className="list-note"><ShieldCheck size={15}/>{module==='categories'?'Inactive categories stay available in historical records.':module==='reconciliations'?'A physical count preserves its recorded snapshot. Approval does not adjust cash.':module==='replenishments'?'Approval authorizes funding. Posting confirms receipt and updates cash once.':'Actions shown here depend on your preview role and each record’s status.'}</div></>}
function MiniStat({label,value,icon:Icon}){return <div><span className="mini-stat-icon"><Icon size={20}/></span><span><small>{label}</small><strong>{value}</strong></span></div>}
function downloadCSV(rows,name){const out=rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k,v])=>['string','number','boolean'].includes(typeof v)).map(([k,v])=>['amount','authorized','physical','recorded','release','returned','excess'].includes(k)&&typeof v==='number'?[k+'_php',(v/100).toFixed(2)]:[k,v])));const keys=[...new Set(out.flatMap(Object.keys))];const csv=[keys,...out.map(r=>keys.map(k=>r[k]??''))].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}

function Detail({module,id}){const {db,role,navigate,confirm,commit}=useApp();const cfg=modules[module],r=db[cfg.type]?.find(x=>x.id===id);if(!r)return <Empty title="Record not found" action={<Btn onClick={()=>navigate('/'+module)}>Back to {cfg.label}</Btn>}/>;if(role==='requester'&&r.owner&&r.owner!==roles[role].name)return <Empty title="This record is outside your scope" text="Requesters can view their own transactions."/>;const fund=db.funds.find(f=>f.id===(module==='funds'?r.id:r.fund));const ask=(title,action,message,extra={})=>confirm({title,action:title.replace('?',''),message,...extra,onConfirm:data=>commit({...action,...data},`${title.replace('?','')} completed.`)});const feedback=(type,status,label)=>ask(label+'?',{type,id,status},'Your reason will be added to the activity history and shown to the record owner.',{reason:true,icon:CircleAlert});const editButton=<Btn icon={Settings2} onClick={()=>navigate(`/${module}/${id}/edit`)}>Edit {cfg.singular}</Btn>;
const actions=[];if(can(role,'editAll'))actions.push(React.cloneElement(editButton,{key:'super-edit'}));if(module==='cash-requests'){
if(!can(role,'editAll')&&can(role,'request')&&r.owner===roles[role].name&&['Draft','Needs Changes'].includes(r.status))actions.push(editButton);
if(can(role,'approveRequest')&&r.status==='Pending Approval')actions.push(<Btn key="changes" onClick={()=>feedback('requestDecision','Needs Changes','Request Changes')}>Request Changes</Btn>,<Btn key="reject" variant="danger-outline" onClick={()=>feedback('requestDecision','Rejected','Reject Cash Request')}>Reject</Btn>,<Btn key="approve" variant="primary" icon={Check} onClick={()=>ask('Approve Cash Request?',{type:'requestDecision',id,status:'Approved'},`Authorize ${money(r.amount)} for ${r.owner}. Cash will change only when the custodian records the release.`)}>Approve Request</Btn>);
if(can(role,'request')&&(can(role,'editAll')||r.owner===roles[role].name)&&['Draft','Needs Changes','Pending Approval','Approved'].includes(r.status))actions.push(<Btn key="personal" onClick={()=>confirm({icon:ReceiptText,title:'Use personal funds instead?',message:'This cancels the unreleased cash advance and creates a reimbursement draft. The custodian will no longer be able to release this request. Enter actual expenses and receipts before submitting.',action:'Cancel Advance & Create Draft',onConfirm:()=>commit({type:'convertToReimbursement',id,confirmed:true},'Cash advance cancelled. Complete the reimbursement draft.',result=>'/reimbursements/'+result.id+'/edit')})}>Use personal funds instead</Btn>);
if(r.convertedTo)actions.push(<Btn key="claim" onClick={()=>navigate('/reimbursements/'+r.convertedTo)}>View Reimbursement</Btn>);
if(can(role,'release')&&r.status==='Approved')actions.push(<Btn key="release" variant="primary" icon={Banknote} onClick={()=>ask('Release Cash?',{type:'release',id},`Record ${money(r.amount)} handed to ${r.owner}. This reduces ${fund.name} recorded cash once.`,{receipt:`I confirm ${r.owner} received ${money(r.amount)}.`,referenceLabel:'Cash release voucher'})}>Release Cash</Btn>);
if(can(role,'liquidate')&&eligibleRequests(db,role).some(x=>x.id===id))actions.push(<Btn key="liquidate" variant="primary" icon={ReceiptText} onClick={()=>navigate('/liquidations/new?request='+id)}>Create Liquidation</Btn>);
}else if(module==='liquidations'){
if(!can(role,'editAll')&&can(role,'liquidate')&&r.owner===roles[role].name&&['Draft','Needs Correction'].includes(r.status))actions.push(editButton);
if(can(role,'verify')&&r.status==='Submitted'){
if(can(role,'editAll')&&!r.returnConfirmed)actions.push(<Btn key='reject' variant='danger-outline' onClick={()=>feedback('liquidationReject',null,'Reject Liquidation')}>Reject</Btn>);
if(r.returned>0&&!r.returnConfirmed)actions.push(<Btn key="return" icon={ArrowDownLeft} onClick={()=>ask('Confirm Cash Return?',{type:'confirmReturn',id},`Expected unused cash: ${money(r.returned)}. Record the actual receipt before verifying this liquidation.`,{receipt:`I physically received ${money(r.returned)} from ${r.owner}.`,referenceLabel:'Cash return voucher'})}>Confirm Cash Return</Btn>);
actions.push(<Btn key="correct" onClick={()=>feedback('liquidationCorrection',null,'Return for Correction')}>Return for Correction</Btn>,<Btn key="verify" variant="primary" icon={CheckCheck} disabled={r.returned>0&&!r.returnConfirmed} title={r.returned&&!r.returnConfirmed?'Confirm returned cash first':undefined} onClick={()=>ask('Verify Liquidation?',{type:'verify',id},r.excess?'Verify the actual expenses. Finance must resolve the reimbursement before settlement.':'Accept the expense evidence and settle this advance. Actual expenses will become eligible for replenishment.')}>Verify Liquidation</Btn>)}
if(can(role,'reimburse')&&r.status==='Verified'&&r.excess)actions.push(<Btn key="pay" variant="primary" onClick={()=>ask('Record Reimbursement Payment?',{type:'reimburse',id},`Authorize and record an actual ${money(r.excess)} reimbursement. If paid outside petty cash, no fund cash-out will be recorded.`,{payment:true,receipt:'I confirm this reimbursement was authorized and actually paid.',referenceLabel:'Payment reference'})}>Record Reimbursement</Btn>);
}else if(module==='replenishments'){
if(!can(role,'editAll')&&can(role,'replenish')&&['Draft','Needs Changes'].includes(r.status))actions.push(editButton);
if(can(role,'approveReplenishment')&&r.status==='Pending Approval')actions.push(<Btn key="changes" onClick={()=>feedback('replenishmentDecision','Needs Changes','Return for Correction')}>Return for Correction</Btn>,...(can(role,'editAll')?[<Btn key='reject' variant='danger-outline' onClick={()=>feedback('replenishmentDecision','Rejected','Reject Replenishment')}>Reject</Btn>]:[]),<Btn key="approve" variant="primary" onClick={()=>ask('Approve Replenishment?',{type:'replenishmentDecision',id,status:'Approved'},`Authorize ${money(r.amount)} for ${fund.name}. Recorded cash remains unchanged until funding receipt is posted.`)}>Approve Replenishment</Btn>);
if(can(role,'approveReplenishment')&&r.status==='Approved')actions.push(<Btn key="post" variant="primary" icon={CheckCheck} onClick={()=>ask('Post Replenishment?',{type:'postReplenishment',id},`Posting restores ${money(r.amount)} to ${fund.name}, marks the included expenses as replenished, and records one ledger transaction.`,{receipt:`I confirm ${money(r.amount)} funding was actually received.`,referenceLabel:'Funding receipt reference'})}>Post Replenishment</Btn>);
}else if(module==='reconciliations'){
if(!can(role,'editAll')&&can(role,'count')&&['Draft','Needs Correction'].includes(r.status))actions.push(editButton);
if(can(role,'approveCount')&&r.status==='Pending Approval')actions.push(<Btn key="change" onClick={()=>feedback('countDecision','Needs Correction','Return for Correction')}>Return for Correction</Btn>,...(can(role,'editAll')?[<Btn key='reject' variant='danger-outline' onClick={()=>feedback('countDecision','Rejected','Reject Reconciliation')}>Reject</Btn>]:[]),<Btn key="approve" variant="primary" onClick={()=>ask('Approve Reconciliation?',{type:'countDecision',id,status:'Approved'},r.physical!==r.recorded?'Accept this count record and its variance for investigation. The shortage or overage remains recorded. No ledger adjustment will be made.':'Accept the reconciled physical cash count. This action does not create a cash movement.')}>Approve Reconciliation</Btn>);
}else if(module==='funds'&&can(role,'manage')){
if(!can(role,'editAll')&&r.status!=='Pending Approval')actions.push(editButton);
if(r.status==='Pending Approval')actions.push(<Btn key="change" onClick={()=>feedback('fundDecision','Needs Changes','Return for Changes')}>Return for Changes</Btn>,<Btn key="reject" variant="danger-outline" onClick={()=>feedback('fundDecision','Rejected','Reject Fund')}>Reject</Btn>,<Btn key="approve" variant="primary" onClick={()=>ask('Approve Petty Cash Fund?',{type:'fundDecision',id,status:'Active'},'Once approved, this fund will become available for eligible petty cash transactions. Authorization alone does not record funding received.')}>Approve Fund</Btn>);
if(['Active','Inactive'].includes(r.status))actions.push(<Btn key="toggle" onClick={()=>ask(`${r.status==='Active'?'Deactivate':'Activate'} Fund?`,{type:'fundToggle',id},'Historical records will be preserved. Only Active funds are eligible for new cash requests.')}>{r.status==='Active'?'Deactivate':'Activate'}</Btn>);
if(r.status==='Active'&&!db.movements.some(m=>m.fund===r.id&&m.type==='Opening funding'))actions.push(<Btn key="open" variant="primary" onClick={()=>ask('Record Opening Funding?',{type:'openingFunding',id},`Record the actual receipt of ${money(r.authorized)} opening cash. This cash-in can only be posted once.`,{receipt:'I confirm the authorized opening cash was actually received.',referenceLabel:'Opening funding reference'})}>Record Opening Funding</Btn>);
}
const source=module==='liquidations'?db.requests.find(q=>q.id===r.request):null;
return <><PageHeading title={module==='funds'?r.name:r.id} description={module==='cash-requests'?r.purpose:module==='funds'?r.code:`${cfg.singular} · ${fund?.name||''}`} back={{path:'/'+module,label:'Back to '+cfg.label}}>{actions}</PageHeading><div className="detail-status-row"><Pill status={r.status}/><span>{r.fixture?'Sample record':'Created this session'}</span>{r.status==='Released'&&r.due<TODAY&&<Pill status="Overdue"/>}{r.replenished&&<span className="replenished"><CircleCheck size={14}/> Replenished</span>}</div><div className="detail-grid"><div className="detail-body">
{r.history?.at(-1)?.note&&['Needs Changes','Needs Correction'].includes(r.status)&&<Notice type="warning"><strong>Changes requested</strong><p>{r.history.at(-1).note}</p></Notice>}
{module==='cash-requests'&&<><Section title="General information"><Summary entries={[["Cash request no.",r.id],["Requester",<div className="person"><Avatar name={r.owner}/>{r.owner}</div>],["Department",r.department],["Petty cash fund",fund.name],["Request date",dateLabel(r.date)],["Required date",dateLabel(r.required)],["Purpose",r.purpose],["Requested amount",money(r.amount)],...(r.releaseDate&&['Released','Liquidated','Closed'].includes(r.status)?[["Release date",dateLabel(r.releaseDate)],["Liquidation due",dateLabel(r.due)],["Cash release voucher",r.reference]]:[])]}/></Section><Section title="Estimated expense items" description="Estimates used for approval; actual expenses are recorded in the liquidation."><ExpenseReadTable items={r.items}/><div className="total-line"><span>Total requested amount</span><strong>{money(r.amount)}</strong></div></Section>{db.liquidations.some(l=>l.request===id)&&<Section title="Linked liquidation">{db.liquidations.filter(l=>l.request===id).map(l=><div className="linked-record" key={l.id}><ReceiptText size={22}/><button className="text-link" onClick={()=>navigate((l.kind==='Reimbursement'?'/reimbursements/':'/liquidations/')+l.id)}>{l.id}</button><Pill status={l.status}/><strong>{money(sum(l.items))}</strong><span>actual expenses</span></div>)}</Section>}{r.notes&&<Section title="Notes"><p className="body-copy">{r.notes}</p></Section>}</>}
{module==='liquidations'&&<><Section title="Request summary"><Summary entries={[["Cash Request",<button className="text-link" onClick={()=>navigate('/cash-requests/'+source.id)}>{source.id}<ExternalLink size={13}/></button>],["Requester",r.owner],["Department",source.department],["Petty cash fund",fund.name],["Release date",dateLabel(source.releaseDate)],["Release amount",money(r.release)],["Overall purpose",source.purpose],["Liquidation date",dateLabel(r.date)]]}/></Section><Section title="Actual expense items" description="Actual spending and supporting evidence linked to this advance."><ExpenseReadTable items={r.items} actual/></Section><div className="settlement-grid"><Section title="Cash return & settlement">{r.returned>0?<><div className="return-box"><span className="stat-icon green"><ArrowDownLeft size={22}/></span><span><small>Expected unused cash</small><strong>{money(r.returned)}</strong></span></div><Notice type={r.returnConfirmed?'success':'warning'}>{r.returnConfirmed?'Cash return confirmed and recorded in the ledger.':'The custodian must confirm physical receipt before verification.'}</Notice></>:<Notice>No unused cash return is required.</Notice>}{r.excess>0&&<Notice type="warning"><strong>{money(r.excess)} reimbursement {r.reimbursement?.status==='Paid'?'paid':'required'}</strong><p>{r.reimbursement?.status==='Paid'?`${r.reimbursement.source} · ${r.reimbursement.reference}`:'Finance must authorize and record payment before this advance can be settled.'}</p></Notice>}</Section><AmountSummary release={r.release} actual={sum(r.items)} returned={r.returned} returnConfirmed={r.returnConfirmed}/></div></>}
{module==='replenishments'&&<><Section title="Replenishment information"><Summary entries={[["Replenishment no.",r.id],["Petty cash fund",fund.name],["Requested by",r.owner],["Created date",dateLabel(r.date)],["Funding receipt reference",r.reference],["Status",<Pill status={r.status}/>]]}/></Section><Section title="Included settlements" description="Approved / verified expenses from this fund only."><DataTable rows={r.liquidations.map(id=>settlementSources(db).find(l=>l.id===id))} columns={[{key:'id',label:'Settlement No.',render:l=><button className="text-link" onClick={()=>navigate((l.kind==='Reimbursement'?'/reimbursements/':'/liquidations/')+l.id)}>{l.id}</button>},{key:'request',label:'Cash Request No.',render:l=>l.request?<button className="text-link" onClick={()=>navigate('/cash-requests/'+l.request)}>{l.request}</button>:'Personal funds'},{key:'owner',label:'Requester'},{key:'actual',label:'Actual expenses',align:'right',render:l=>money(sum(l.items))},{key:'eligible',label:'Fund replenishment',align:'right',render:l=>money(replenishAmount(l))}]}/><div className="total-line"><span>{r.liquidations.length} settlement{r.liquidations.length!==1?'s':''} · total replenishment</span><strong>{money(r.amount)}</strong></div></Section><Notice>{r.status==='Posted'?'Funding receipt is posted in the ledger. These settlements cannot be replenished again.':r.status==='Approved'?'Approved for funding. Post only after the cash has actually been received.':'Submission and approval do not increase recorded cash. Posting confirms actual funding receipt.'}</Notice></>}
{module==='reconciliations'&&<><Section title="Cash count information"><Summary entries={[["Reconciliation no.",r.id],["Petty cash fund",fund.name],["Counted by",r.owner],["Count date",dateLabel(r.date)]]}/></Section><div className="count-summary"><div><small>Recorded cash at count</small><strong>{money(r.recorded)}</strong></div><div><small>Physical cash counted</small><strong>{money(r.physical)}</strong></div><div className={r.physical!==r.recorded?'variance':'matched'}><small>{r.physical<r.recorded?'Cash shortage':r.physical>r.recorded?'Cash overage':'Reconciled'}</small><strong>{money(r.physical-r.recorded)}</strong></div></div>{r.physical!==r.recorded&&<Notice type="warning">Variance preserved for investigation. Approval of the count does not resolve the discrepancy or alter the ledger.</Notice>}<Section title="Variance explanation & notes"><p className="body-copy">{r.reason||'No variance recorded.'}</p>{r.notes&&<p className="muted">{r.notes}</p>}</Section></>}
{module==='funds'&&<><Section title={r.proposed?'Proposed fund amendment':'Fund authorization'}><Summary entries={[["Fund code",r.code],["Fund name",r.proposed?.name||r.name],["Currency","PHP · Philippine peso"],["Custodian",r.proposed?.custodian||r.custodian],["Authorized amount",money(r.proposed?.authorized||r.authorized)],["Recorded cash",money(balance(db,r.id))],["Replenishment threshold",`${r.proposed?.threshold||r.threshold}% remaining (demo policy)`],["Liquidation deadline",`${r.proposed?.deadline||r.deadline} calendar days from release (demo policy)`],["Description",r.proposed?.description||r.description]]}/></Section><Notice>Fund authorization and cash received are separate. Opening funding is recorded only on actual receipt.</Notice><Section title="Fund movement history" description="All recorded cash movements for this fund, in chronological order."><MovementTable fund={r.id}/></Section></>}
</div><History record={r}/></div></>}
function ExpenseReadTable({items,actual=false}){return <div className="table-scroll"><table className="expense-table"><thead><tr><th>#</th><th>Expense category</th><th>Description{actual?' / Payee':''}</th>{actual&&<th>Expense date</th>}<th className="align-right">{actual?'Actual':'Estimated'} amount</th>{<th>{actual?'Receipt':'Supporting document'}</th>}</tr></thead><tbody>{items.map((i,n)=><tr key={i.id}><td className="muted">{n+1}</td><td>{i.category}</td><td>{i.description}{actual&&<small>{i.payee}</small>}</td>{actual&&<td>{dateLabel(i.date)}</td>}<td className="align-right numeric">{money(i.amount)}</td>{<td>{i.receipt?<ReceiptLink receipt={i.receipt}/>:actual?<span className='warning-text'>Missing receipt</span>:'—'}</td>}</tr>)}</tbody></table></div>}
function ReceiptLink({receipt}){const {setModal}=useApp();const [open,setOpen]=useState(false);return <>{receipt?.url?<button className="receipt-link" onClick={()=>setOpen(true)}><Paperclip size={13}/>{receipt.sample?'Sample receipt':receipt.name}<ExternalLink size={12}/></button>:<span className="warning-text">Missing receipt</span>}{open&&<Modal title={receipt.name} description={receipt.sample?'Demonstration document · not evidence of a real purchase':'Local file available for this session only'} onClose={()=>setOpen(false)} wide><div className="receipt-preview">{/pdf/i.test(receipt.name)?<iframe src={receipt.url} title="Receipt preview"/>:<img src={receipt.url} alt="Supporting expense receipt"/>}</div></Modal>}</>}

function TransactionForm({module,id}){const {db,role,navigate,commit,confirm,setDirty,notify}=useApp();const cleanModule=module;const cfg=modules[module];const record=id?db[cfg.type].find(r=>r.id===id):null;const activeFunds=db.funds.filter(f=>f.status==='Active');const permitted=module==='cash-requests'?can(role,'request'):module==='liquidations'?can(role,'liquidate'):module==='replenishments'?can(role,'replenish'):module==='reconciliations'?can(role,'count'):can(role,'manage');const seed=()=>{if(record)return {...structuredClone(record),items:record.items?.map(i=>({...i,value:(i.amount/100).toFixed(2),inherited:true})),authorizedValue:((record.proposed?.authorized||record.authorized||0)/100).toFixed(2),physicalValue:((record.physical||0)/100).toFixed(2),returnedValue:((record.returned||0)/100).toFixed(2),...record.proposed};return {fund:activeFunds[0]?.id||'',date:TODAY,required:TODAY,purpose:'',notes:'',items:[blankItem()],request:'',returnedValue:'0.00',liquidations:[],recorded:balance(db,activeFunds[0]?.id),physicalValue:'',reason:'',code:'',name:'',location:'',authorizedValue:'',custodian:'Sofia Cruz',threshold:25,deadline:3,description:''}};
const locked=can(role,'editAll')&&financialFieldsLocked(db,cfg.type,record);const [v,setV]=useState(seed),[lookup,setLookup]=useState(null),[errors,setErrors]=useState('');const change=(key,value)=>{setV(x=>({...x,[key]:value}));setDirty(true);setErrors('')};const chooseRequest=r=>{setV(x=>({...x,request:r.id,fund:r.fund,items:r.items.map(i=>({...i,id:crypto.randomUUID(),inherited:true,value:(i.amount/100).toFixed(2),receipt:undefined,date:TODAY,payee:''})),returnedValue:'0.00'}));setDirty(true)};
useEffect(()=>{if(module==='liquidations'&&!id){const requested=routeQuery('request');const r=eligibleRequests(db,role).find(r=>r.id===requested);if(r)chooseRequest(r)}return()=>setDirty(false)},[]);
if(!permitted)return <Empty title="This action belongs to another role" text="Use the role preview to explore this workflow."/>;if(id&&!record)return <Empty title="Record not found"/>;if(record&&!can(role,'editAll')&&module==='cash-requests'&&(record.owner!==roles[role].name||!['Draft','Needs Changes'].includes(record.status)))return <Empty title="This request is not editable"/>;if(record&&!can(role,'editAll')&&module==='liquidations'&&(record.owner!==roles[role].name||!['Draft','Needs Correction'].includes(record.status)))return <Empty title="This liquidation is not editable"/>;
const selectedRequest=db.requests.find(r=>r.id===v.request);const parseItems=()=>v.items.map(i=>({...i,amount:cents(i.value)}));const total=v.items?.reduce((n,i)=>{try{return n+cents(i.value,true)}catch{return n}},0)||0;let returned=0;try{returned=cents(v.returnedValue||'0',true)}catch{};
const save=submit=>{try{if(locked){commit({type:'saveTransactionNotes',recordType:cfg.type,id,notes:v.notes},'Transaction notes updated.','/'+module);return}let value={...v};if(module==='cash-requests'||module==='liquidations')value.items=parseItems();if(module==='liquidations'){if(!selectedRequest)throw Error('Select an eligible released cash request.');value.returned=cents(v.returnedValue,true);if(submit){if(!value.items.length)throw Error('Add at least one actual expense.');if(value.items.some(i=>!i.receipt?.url))throw Error('Attach a PDF, JPG, or PNG receipt to every actual expense.');if(value.items.some(i=>!i.payee?.trim()))throw Error('Enter the merchant or payee on every expense line.');if(value.returned!==Math.max(0,selectedRequest.amount-sum(value.items)))throw Error('Returned cash must match the unused advance shown in the summary.')}}if(['cash-requests','liquidations'].includes(module)){if(!value.items.length||value.items.some(i=>!i.category||!i.description.trim()))throw Error('Complete at least one expense line with a category, description, and amount.');if(module==='cash-requests'&&(!v.purpose.trim()||!v.required||!v.fund))throw Error('Complete the fund, purpose, and required date.')}if(module==='reconciliations'){value.physical=cents(v.physicalValue,true);if(value.physical!==v.recorded&&!v.reason.trim())throw Error('Explain the cash shortage or overage before saving.')}if(module==='replenishments'&&!v.liquidations.length)throw Error('Select at least one eligible settlement.');if(module==='funds'){value.authorized=cents(v.authorizedValue);if(!v.code.trim()||!v.name.trim())throw Error('Enter a fund code and fund name.');value.threshold=Number(v.threshold);value.deadline=Number(v.deadline)}const type={'cash-requests':'saveRequest',liquidations:'saveLiquidation',replenishments:'saveReplenishment',reconciliations:'saveCount',funds:'saveFund'}[module];const action={type,id,value,submit};if(submit)confirm({title:`${record&&['Needs Changes','Needs Correction'].includes(record.status)?'Resubmit':'Submit'} ${cfg.singular}?`,action:module==='liquidations'?'Submit Liquidation':'Submit for Approval',icon:Send,message:module==='liquidations'?'Your liquidation will be sent to the Petty Cash Custodian for verification. Please make sure the expense details, receipts, and returned cash information are complete.':'This record will be sent to the responsible reviewer. Submission does not move cash.',onConfirm:()=>commit(action,`${cfg.singular} submitted successfully.`,'/'+module)});else commit(action,`${cfg.singular} draft saved.`,'/'+module)}catch(e){setErrors(e.message);notify(e.message,'error')}};
return <><PageHeading title={`${id?'Edit':'Create'} ${cfg.singular}`} back={{path:'/'+module,label:'Back to '+cfg.label}}><Btn onClick={()=>navigate('/'+module)}>Cancel</Btn><Btn onClick={()=>save(false)}>{record?'Save Changes':'Save as Draft'}</Btn>{!locked&&<Btn variant="primary" icon={Send} onClick={()=>save(true)}>{['Needs Correction','Needs Changes'].includes(record?.status)?'Resubmit':'Submit'}</Btn>}</PageHeading>{errors&&<div className="form-errors"><Notice type="error">{errors}</Notice></div>}<div className="form-layout"><div className="form-main">{locked&&<Notice>Cash has already been recorded for this transaction. Super User can update notes; posted amounts and source relationships remain protected.</Notice>}<fieldset className="transaction-fields" disabled={locked}>
{module==='cash-requests'&&<Section title="General information" description="Tell us what you need and when you need it."><div className="form-grid"><Field label="Requester">{can(role,'editAll')?<select value={v.owner||roles[role].name} onChange={e=>{change('owner',e.target.value);change('department',db.requests.find(r=>r.owner===e.target.value)?.department||'Administration')}}>{[...new Set([roles[role].name,...db.requests.map(r=>r.owner)])].map(name=><option key={name}>{name}</option>)}</select>:<input readOnly value={record?.owner||roles[role].name}/>}</Field><Field label="Department"><input readOnly value={v.department||(can(role,'editAll')?'Administration':'Marketing')}/></Field><Field label="Petty cash fund" required><select value={v.fund} onChange={e=>change('fund',e.target.value)}>{activeFunds.map(f=><option key={f.id} value={f.id}>{f.name} · {f.code}</option>)}</select></Field><Field label="Request date"><input type="date" value={v.date} readOnly/></Field><Field label="Required date" required><input type="date" min={v.date} value={v.required} onChange={e=>change('required',e.target.value)}/></Field><Field label="Overall purpose" required className="span-all"><textarea rows="2" placeholder="e.g. Transportation and working lunch for the client site visit" value={v.purpose} onChange={e=>change('purpose',e.target.value)}/></Field></div></Section>}
{module==='liquidations'&&<><Section title="Select your cash request" description="Start with an advance that has been released to you."><Field label="Cash Request" required><button className="lookup-input" disabled={!!record} onClick={()=>setLookup('request')}><span>{v.request||'Select a released Cash Request'}</span><Search size={17}/></button></Field>{!selectedRequest?<Notice>Only your released requests without an existing liquidation are available.</Notice>:<div className="source-summary"><Summary entries={[["Requester",selectedRequest.owner],["Department",selectedRequest.department],["Petty cash fund",db.funds.find(f=>f.id===selectedRequest.fund)?.name],["Release date",dateLabel(selectedRequest.releaseDate)],["Release amount",money(selectedRequest.amount)],["Overall purpose",selectedRequest.purpose]]}/></div>}</Section>{selectedRequest&&<Notice>Estimated items have been copied as starting values. Update actual amounts, add payees and receipts, and adjust the items to match your spending.</Notice>}</>}
{['cash-requests','liquidations'].includes(module)&&(module==='cash-requests'||selectedRequest)&&<Section title={module==='liquidations'?'Actual expense items':'Estimated expense items'} description={module==='liquidations'?'Record what you actually spent. Receipts stay in this browser session.':'Add the expected costs for this cash advance.'} action={<Btn variant="small" icon={Plus} onClick={()=>change('items',[...v.items,blankItem()])}>Add Item</Btn>}><ExpenseEditor items={v.items} actual={module==='liquidations'} onChange={items=>change('items',items)}/><div className="total-line"><span>Total {module==='liquidations'?'actual expenses':'requested amount'}</span><strong>{money(total)}</strong></div></Section>}
{module==='liquidations'&&selectedRequest&&<Section title="Unused cash return" description="Enter the amount you will return to the custodian."><div className="form-grid two"><Field label="Returned cash" required hint={`Expected return: ${money(Math.max(0,selectedRequest.amount-total))}`}><div className="currency-input"><span>₱</span><input inputMode="decimal" value={v.returnedValue} onChange={e=>change('returnedValue',e.target.value)}/></div></Field><div className="return-hint"><Info size={17}/><span>A claimed return is recorded as cash only when the custodian confirms receipt.</span></div></div></Section>}
{module==='replenishments'&&<><Section title="Replenishment information"><div className="form-grid two"><Field label="Petty cash fund" required><select value={v.fund} onChange={e=>{change('fund',e.target.value);change('liquidations',[])}}>{activeFunds.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></Field><Field label="Requested by"><input readOnly value={record?.owner||roles[role].name}/></Field><Field label="Created date"><input readOnly value={dateLabel(TODAY)}/></Field><Field label="Current recorded cash"><input readOnly value={money(balance(db,v.fund))}/></Field></div></Section><Section title="Included settlements" description="Choose liquidated advances or paid reimbursements from this fund. Selected records are reserved on save." action={<Btn icon={Plus} variant="small" onClick={()=>setLookup('liquidation')}>Select Settlements</Btn>}>{v.liquidations.length?<div className="table-scroll"><table><thead><tr><th>Settlement No.</th><th>Cash Request No.</th><th>Requester</th><th className="align-right">Actual / eligible amount</th><th/></tr></thead><tbody>{v.liquidations.map(id=>{const l=settlementSources(db).find(x=>x.id===id);return <tr key={id}><td>{l.id}</td><td>{l.request||'Personal funds'}</td><td>{l.owner}</td><td className="align-right">{money(replenishAmount(l))}</td><td><IconButton icon={Trash2} label={`Remove ${id}`} onClick={()=>change('liquidations',v.liquidations.filter(x=>x!==id))}/></td></tr>})}</tbody></table></div>:<Empty title="Select eligible settlements" text="Only settled, unreserved expenses paid by the selected fund can be included." action={<Btn icon={Plus} onClick={()=>setLookup('liquidation')}>Select Settlements</Btn>}/>}<div className="total-line"><span>{v.liquidations.length} selected · total replenishment</span><strong>{money(v.liquidations.reduce((n,id)=>n+replenishAmount(settlementSources(db).find(l=>l.id===id)),0))}</strong></div></Section><Notice>Finance approval and funding receipt are separate steps. Posting the received funding restores the cash balance.</Notice></>}
{module==='reconciliations'&&<><Section title="Physical cash count" description="Count the cash on hand and compare it with the recorded snapshot."><div className="form-grid two"><Field label="Petty cash fund" required><select value={v.fund} disabled={!!record} onChange={e=>{change('fund',e.target.value);change('recorded',balance(db,e.target.value))}}>{activeFunds.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></Field><Field label="Reconciliation date" required><input type="date" value={v.date} max={TODAY} onChange={e=>change('date',e.target.value)}/></Field><Field label="Recorded cash" hint="Snapshot retained with this count"><input readOnly value={money(v.recorded)}/></Field><Field label="Physical cash count" required hint="Zero is a valid physical count."><div className="currency-input"><span>₱</span><input inputMode="decimal" value={v.physicalValue} onChange={e=>change('physicalValue',e.target.value)} placeholder="0.00"/></div></Field></div><Variance recorded={v.recorded} physical={v.physicalValue}/><Field label="Variance reason" required={Number(v.physicalValue)*100!==v.recorded}><textarea rows="3" value={v.reason} onChange={e=>change('reason',e.target.value)} placeholder="Explain any shortage or overage and next investigation steps"/></Field></Section><Notice>Submitting or approving a reconciliation does not adjust the fund balance. A variance remains visible for investigation.</Notice></>}
{module==='funds'&&<><Section title="Fund information" description="Fund creation and amendments require approval before use."><div className="form-grid two"><Field label="Fund code" required><input value={v.code} onChange={e=>change('code',e.target.value)} placeholder="PCF-DVO"/></Field><Field label="Fund name" required><input value={v.name} onChange={e=>change('name',e.target.value)} placeholder="Davao Branch"/></Field><Field label="Currency"><input readOnly value="PHP · Philippine peso"/></Field><Field label="Authorized amount" required><div className="currency-input"><span>₱</span><input inputMode="decimal" value={v.authorizedValue} onChange={e=>change('authorizedValue',e.target.value)} placeholder="0.00"/></div></Field><Field label="Custodian" required><select value={v.custodian} onChange={e=>change('custodian',e.target.value)}><option>Sofia Cruz</option></select></Field><Field label="Location"><input value={v.location} onChange={e=>change('location',e.target.value)} placeholder="City / office"/></Field><Field label="Replenishment threshold (%)" required><input type="number" min="1" max="100" value={v.threshold} onChange={e=>change('threshold',e.target.value)}/></Field><Field label="Liquidation deadline (calendar days)" required><input type="number" min="1" step="1" value={v.deadline} onChange={e=>change('deadline',e.target.value)}/></Field><Field label="Description" className="span-all"><textarea value={v.description} rows="3" onChange={e=>change('description',e.target.value)}/></Field></div></Section><Notice>Approval authorizes this fund. Opening cash receipt is recorded separately after activation. Threshold and deadline are demonstration assumptions.</Notice></>}
</fieldset>{module!=='funds'&&<Section title="Additional notes"><Field label="Notes"><textarea placeholder="Add context or instructions for the reviewer (optional)" rows="3" value={v.notes} onChange={e=>change('notes',e.target.value)}/></Field></Section>}</div><aside className="form-aside">{module==='liquidations'&&selectedRequest?<AmountSummary release={selectedRequest.amount} actual={total} returned={returned}/>:<div className="form-guide"><span className="form-guide-icon"><cfg.icon size={24}/></span><h3>{module==='replenishments'?'Restore with confidence':module==='reconciliations'?'Every peso accounted for':module==='funds'?'A controlled cash fund':module==='liquidations'?'Start with your released advance':'A clear request gets a faster decision'}</h3><p>{module==='cash-requests'?'Use one overall purpose and add each estimated expense as its own line. Your approver will review the combined amount.':module==='liquidations'?'Choose your released cash request. Its estimates will be copied so you can record actual spending and supporting receipts.':module==='replenishments'?'The total comes from eligible actual expenses, not the original cash advances. An expense can be replenished only once.':module==='reconciliations'?'Count notes and coins before entering the physical amount. Explain every difference for the Finance reviewer.':'Assign a custodian, an authorized amount, and operating rules before submitting for approval.'}</p><div><ShieldCheck size={16}/> Session-only prototype</div></div>}</aside></div>
{lookup&&<Lookup kind={lookup} id={id} fund={v.fund} selected={lookup==='request'?[v.request]:v.liquidations} onClose={()=>setLookup(null)} onSelect={rows=>{if(lookup==='request')chooseRequest(rows[0]);else change('liquidations',rows.map(r=>r.id));setLookup(null)}}/>}</>}
function routeQuery(key){return new URLSearchParams(location.hash.split('?')[1]||'').get(key)}
function ExpenseEditor({items,actual,onChange}){const {db,notify}=useApp();const update=(id,key,value)=>onChange(items.map(i=>i.id===id?{...i,[key]:value}:i));const file=async(i,f)=>{if(!f)return;if(!['application/pdf','image/jpeg','image/png'].includes(f.type)){notify('Choose a PDF, JPG, or PNG file.','error');return}try{const digest=await crypto.subtle.digest('SHA-256',await f.arrayBuffer());const hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');update(i.id,'receipt',{name:f.name,url:URL.createObjectURL(f),type:f.type,size:f.size,hash})}catch{notify('The receipt could not be read. Please attach it again.','error')}};return <div className="expense-editor">{items.map((i,n)=><div className="expense-line" key={i.id}><div className="line-number">{n+1}</div><div className="line-fields"><div className="line-main"><Field label="Expense category" required>{i.inherited?<input readOnly value={i.category}/>:<select value={i.category} onChange={e=>update(i.id,'category',e.target.value)}><option value="">Select category</option>{db.categories.filter(c=>c.status==='Active').map(c=><option key={c.id}>{c.name}</option>)}</select>}</Field><Field label="Description" required><input value={i.description} placeholder="Describe the expense" onChange={e=>update(i.id,'description',e.target.value)}/></Field><Field label={actual?'Actual amount':'Estimated amount'} required><div className="currency-input"><span>₱</span><input aria-label={`${actual?'Actual':'Estimated'} amount item ${n+1}`} inputMode="decimal" value={i.value} placeholder="0.00" onChange={e=>update(i.id,'value',e.target.value)}/></div></Field><IconButton icon={Trash2} label={`Remove expense item ${n+1}`} onClick={()=>onChange(items.filter(x=>x.id!==i.id))}/></div>{actual&&<div className="line-extra"><Field label="Actual expense date" required><input type="date" max={TODAY} value={i.date} onChange={e=>update(i.id,'date',e.target.value)}/></Field><Field label="Merchant / payee" required><input value={i.payee} placeholder="Business or person paid" onChange={e=>update(i.id,'payee',e.target.value)}/></Field><div className="field"><span>Receipt / supporting document <b>*</b></span>{i.receipt?<div className="attached-file"><ReceiptLink receipt={i.receipt}/><IconButton icon={X} label="Remove receipt" onClick={()=>update(i.id,'receipt',null)}/></div>:<label className="file-upload"><Paperclip size={15}/><span>Attach receipt</span><input type="file" accept=".pdf,.jpg,.jpeg,.png" aria-label={`Attach receipt item ${n+1}`} onChange={e=>file(i,e.target.files[0])}/></label>}</div></div>}{!actual&&<div className='estimate-evidence'>{i.receipt?<div className='attached-file'><ReceiptLink receipt={i.receipt}/><IconButton icon={X} label='Remove supporting document' onClick={()=>update(i.id,'receipt',null)}/></div>:<label className='file-upload'><Paperclip size={14}/><span>Supporting document (optional)</span><input type='file' accept='.pdf,.jpg,.jpeg,.png' aria-label={'Attach supporting document item '+(n+1)} onChange={e=>file(i,e.target.files[0])}/></label>}</div>}</div></div>)}{!items.length&&<Empty title="No expense items yet" text="Use Add Item to record an expense."/>}</div>}
function Variance({recorded,physical}){let value;try{value=cents(physical,true)}catch{return <div className="variance-box neutral"><span>Variance</span><strong>Enter a physical count</strong></div>}const diff=value-recorded;return <div className={`variance-box ${diff?'short':'matched'}`}><span>{diff<0?'Cash shortage':diff>0?'Cash overage':'Reconciled'}</span><strong>{money(diff)}</strong></div>}
function Lookup({kind,fund,id,selected,onSelect,onClose}){const {db,role}=useApp();const [query,setQuery]=useState(''),[selection,setSelection]=useState(selected.filter(Boolean));const multi=kind==='liquidation';const rows=(multi?replenishable(db,fund,id):eligibleRequests(db,role)).filter(r=>`${r.id} ${r.purpose||''} ${r.owner} ${r.request||''}`.toLowerCase().includes(query.toLowerCase()));const all=multi?replenishable(db,fund,id):eligibleRequests(db,role);return <Modal title={multi?'Select eligible settlements':'Select a Cash Request'} description={multi?'Liquidated advances and paid petty cash reimbursements from the selected fund.':'Your released advances without an existing liquidation.'} wide onClose={onClose}><div className="lookup-search table-search"><Search size={17}/><input autoFocus aria-label="Search eligible records" placeholder="Search reference, purpose, or requester…" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="table-scroll lookup-table"><table><thead><tr><th/>{multi?<><th>Settlement No.</th><th>Cash Request No.</th><th>Requester</th><th className="align-right">Actual expenses</th></>:<><th>Cash Request No.</th><th>Release date</th><th>Purpose</th><th className="align-right">Release amount</th></>}<th>Status</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} className={selection.includes(r.id)?'selected-row':''}><td><input type={multi?'checkbox':'radio'} name="eligible" aria-label={`Select ${r.id}`} checked={selection.includes(r.id)} onChange={()=>setSelection(multi?(selection.includes(r.id)?selection.filter(x=>x!==r.id):[...selection,r.id]):[r.id])}/></td><td><label className="lookup-label">{r.id}</label></td><td>{multi?(r.request||'Personal funds'):dateLabel(r.releaseDate)}</td><td>{multi?r.owner:r.purpose}</td><td className="align-right numeric">{money(multi?sum(r.items):r.amount)}</td><td><Pill status={r.status}/></td></tr>)}</tbody></table>{!rows.length&&<Empty title="No eligible records" text={multi?'No unreserved, liquidated expenses are available for this fund.':'Your released requests already have a liquidation, or no advance has been released to you yet.'}/>}</div><div className="modal-footer"><span className="selection-count">{selection.length} selected</span><Btn onClick={onClose}>Cancel</Btn><Btn variant="primary" disabled={!selection.length} onClick={()=>onSelect(all.filter(r=>selection.includes(r.id)))}>Select{multi?' Settlements':' Cash Request'}</Btn></div></Modal>}
function CategoryModal({record,onClose}){const {commit,confirm}=useApp();const [name,setName]=useState(record?.name||''),[description,setDescription]=useState(record?.description||''),[status,setStatus]=useState(record?.status||'Active');return <Modal title={record?'Edit Expense Category':'New Expense Category'} onClose={onClose}><div className="modal-body"><Field label="Category" required><input value={name} autoFocus onChange={e=>setName(e.target.value)} placeholder="e.g. Postage & delivery"/></Field><Field label="Description"><textarea rows="3" value={description} onChange={e=>setDescription(e.target.value)}/></Field><Field label="Status"><select value={status} onChange={e=>setStatus(e.target.value)}><option>Active</option><option>Inactive</option></select></Field><Notice>Only Active categories can be selected for new expenses. Historical values are preserved.</Notice></div><div className="modal-footer">{record&&<Btn variant="danger-outline" icon={Trash2} onClick={()=>confirm({icon:Trash2,title:'Delete Expense Category?',danger:true,message:'Only unused categories can be deleted. Categories referenced by transaction history must be deactivated instead.',action:'Delete Category',onConfirm:()=>commit({type:'deleteCategory',id:record.id},'Category deleted.')} )}>Delete</Btn>}<div className="spacer"/><Btn onClick={onClose}>Cancel</Btn><Btn variant="primary" onClick={()=>{if(commit({type:'saveCategory',id:record?.id,value:{name:name.trim(),description,status}},record?'Category updated.':'Category created.'))onClose()}}>{record?'Save Changes':'Save'}</Btn></div></Modal>}

function MovementTable({fund='all',query='',type='all',start='',end=''}){const {db,navigate,role,setModal}=useApp();const totals={};const movements=[...db.movements].sort((a,b)=>a.date.localeCompare(b.date)).map(m=>{totals[m.fund]=(totals[m.fund]||0)+m.amount;return {...m,running:totals[m.fund]}}).filter(m=>(fund==='all'||m.fund===fund)&&(type==='all'||m.type===type)&&(!start||m.date>=start)&&(!end||m.date<=end)&&`${m.source} ${m.actor} ${m.type} ${m.note}`.toLowerCase().includes(query.toLowerCase()));const open=m=>{const module=m.type==='Employee reimbursement'?'reimbursements':m.type==='Cash release'?'cash-requests':['Cash return','Reimbursement'].includes(m.type)?'liquidations':m.type==='Replenishment'?'replenishments':'funds';if(module==='funds')setModal({kind:'movement',record:m});else navigate('/'+module+'/'+m.source)};return <DataTable rows={movements} columns={[{key:'date',label:'Date',render:m=>dateLabel(m.date)},{key:'source',label:'Source reference',render:m=><button className="text-link" onClick={()=>open(m)}>{m.source}</button>},{key:'type',label:'Transaction type',render:m=><div className="movement-type"><span className={`movement-icon ${m.amount>0?'in':'out'}`}>{m.amount>0?<ArrowDownLeft size={15}/>:<ArrowUpRight size={15}/>}</span>{m.type}</div>},{key:'fund',label:'Fund',render:m=>db.funds.find(f=>f.id===m.fund)?.name},{key:'amount',label:'Cash in',align:'right',render:m=>m.amount>0?<strong className="success-text numeric">{money(m.amount)}</strong>:'—'},{key:'out',label:'Cash out',align:'right',value:m=>-m.amount,render:m=>m.amount<0?<strong className="numeric">{money(-m.amount)}</strong>:'—'},{key:'running',label:'Fund running balance',align:'right',render:m=><strong className="numeric">{money(m.running)}</strong>},{key:'actor',label:'Recorded by'}]}/>}
function Ledger(){const {db}=useApp();const [fund,setFund]=useState(routeQuery('fund')||'all'),[query,setQuery]=useState(''),[type,setType]=useState('all');const movements=db.movements.filter(m=>(fund==='all'||m.fund===fund)&&(type==='all'||m.type===type)&&`${m.source} ${m.actor} ${m.type} ${m.note}`.toLowerCase().includes(query.toLowerCase()));return <><PageHeading title="Transaction ledger" description="A complete, traceable record of actual cash movements."><Btn icon={Download} onClick={()=>downloadCSV(movements,'petty-cash-ledger.csv')}>Export ledger</Btn></PageHeading><div className="mini-stats"><MiniStat label="Recorded cash · all movement history" value={money(db.movements.filter(m=>fund==='all'||m.fund===fund).reduce((n,m)=>n+m.amount,0))} icon={Wallet}/><MiniStat label="Cash in · filtered entries" value={money(movements.filter(m=>m.amount>0).reduce((n,m)=>n+m.amount,0))} icon={ArrowDownLeft}/><MiniStat label="Cash out · filtered entries" value={money(-movements.filter(m=>m.amount<0).reduce((n,m)=>n+m.amount,0))} icon={ArrowUpRight}/><MiniStat label="Filtered movements" value={movements.length} icon={BookOpen}/></div><div className="panel"><div className="section-head"><div><h2>Cash movement history</h2><p>Running balances retain each fund’s full chronological history.</p></div><span className="readonly-label"><ShieldCheck size={14}/> Posted records are read-only</span></div><div className="table-toolbar"><div className="table-search"><Search size={16}/><input aria-label="Search ledger" placeholder="Search reference or transaction…" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="filter-controls"><select aria-label="Ledger fund" value={fund} onChange={e=>setFund(e.target.value)}><option value="all">All funds</option>{db.funds.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select><select aria-label="Transaction type" value={type} onChange={e=>setType(e.target.value)}><option value="all">All transaction types</option>{[...new Set(db.movements.map(m=>m.type))].map(x=><option key={x}>{x}</option>)}</select></div></div><MovementTable fund={fund} query={query} type={type}/></div><div className="list-note"><Info size={15}/> Cash counts and expense verification do not create an additional cash-out. Original posted entries are preserved.</div></>}
function Reports(){const {db,navigate,notify}=useApp();const [fund,setFund]=useState('all'),[category,setCategory]=useState('all'),[start,setStart]=useState('2026-10-01'),[end,setEnd]=useState(TODAY),[tab,setTab]=useState('expenses');const valid=start&&end&&start<=end&&end<=TODAY;const items=valid?[...db.liquidations,...db.reimbursements].filter(l=>['Liquidated','Verified','Approved — Pending Payment','Paid'].includes(l.status)&&(fund==='all'||l.fund===fund)).flatMap(l=>l.items.map((i,n)=>({...i,id:l.id+'-'+n,liquidation:l.id,request:l.request,owner:l.owner,fund:l.fund}))).filter(i=>i.date>=start&&i.date<=end&&(category==='all'||i.category===category)):[];const fs=db.funds.filter(f=>(fund==='all'||f.id===fund)&&f.status!=='Draft');const asOf=valid?db.movements.filter(m=>m.date<=end&&(fund==='all'||m.fund===fund)).reduce((n,m)=>n+m.amount,0):0;const advances=valid?db.requests.filter(r=>(fund==='all'||r.fund===fund)&&r.status==='Released'&&r.releaseDate<=end):[];const exportRows=()=>{if(!valid)return notify('Enter a valid date range, ending no later than the demo date.','error');const rows=tab==='expenses'?items.map(i=>({expense_date:i.date,liquidation:i.liquidation,request:i.request,owner:i.owner,fund:db.funds.find(f=>f.id===i.fund)?.name,category:i.category,payee:i.payee,actual_expense_php:(i.amount/100).toFixed(2)})):tab==='advances'?advances.map(r=>({request:r.id,owner:r.owner,release_date:r.releaseDate,due_date:r.due,released_php:(r.amount/100).toFixed(2)})):fs.map(f=>({fund:f.name,authorized_php:(f.authorized/100).toFixed(2),recorded_cash_php:(db.movements.filter(m=>m.fund===f.id&&m.date<=end).reduce((n,m)=>n+m.amount,0)/100).toFixed(2),as_of:end}));downloadCSV(rows,`petty-cash-${tab}-${end}.csv`)};return <><PageHeading title="Reports & insights" description="Understand actual spending, fund positions, and outstanding advances."><Btn icon={Download} onClick={exportRows}>Export report</Btn></PageHeading><div className="panel report-filters"><Field label="Petty cash fund"><select value={fund} onChange={e=>setFund(e.target.value)}><option value="all">All funds</option>{db.funds.map(f=><option key={f.id} value={f.id}>{f.name}</option>)}</select></Field><Field label="Expense category"><select value={category} onChange={e=>setCategory(e.target.value)}><option value="all">All categories</option>{db.categories.map(c=><option key={c.id}>{c.name}</option>)}</select></Field><Field label="From"><input type="date" value={start} max={end} onChange={e=>setStart(e.target.value)}/></Field><Field label="Through / as of"><input type="date" value={end} min={start} max={TODAY} onChange={e=>setEnd(e.target.value)}/></Field></div>{!valid&&<Notice type="error">Enter a valid date range ending no later than {dateLabel(TODAY)}.</Notice>}<div className="mini-stats"><MiniStat label="Approved / verified expenses · selected criteria" value={money(sum(items))} icon={ReceiptText}/><MiniStat label="Recorded cash · fund / as of date" value={money(asOf)} icon={Wallet}/><MiniStat label="Unsettled advances · fund / as of date" value={money(advances.reduce((n,r)=>n+r.amount,0))} icon={Banknote}/><MiniStat label="Expense lines matching criteria" value={items.length} icon={Shapes}/></div><div className="panel"><div className="tabs" role="tablist">{[['expenses','Actual expenses'],['funds','Fund position'],['advances','Outstanding advances']].map(([key,label])=><button role="tab" aria-selected={tab===key} className={tab===key?'active':''} key={key} onClick={()=>setTab(key)}>{label}</button>)}</div><div className="report-basis"><Info size={15}/>{tab==='expenses'?'Date basis: actual expense date. Includes verified liquidations and approved reimbursements, including unpaid claims; original advances are excluded.':tab==='funds'?'Complete fund cash movements through the as-of date. Category criteria do not change fund cash.':'Released advances awaiting accepted settlement, released by the as-of date and still unsettled now. Category criteria do not apply.'}</div>{tab==='expenses'?<DataTable rows={items} columns={[{key:'date',label:'Expense date',render:i=>dateLabel(i.date)},{key:'liquidation',label:'Settlement',render:i=><button className="text-link" onClick={()=>navigate((i.liquidation.startsWith('RMB-')?'/reimbursements/':'/liquidations/')+i.liquidation)}>{i.liquidation}</button>},{key:'owner',label:'Employee'},{key:'category',label:'Category'},{key:'payee',label:'Payee'},{key:'fund',label:'Fund',render:i=>db.funds.find(f=>f.id===i.fund)?.name||'Outside / pending payment'},{key:'amount',label:'Actual expense',align:'right',render:i=><strong className="numeric">{money(i.amount)}</strong>}]}/>:tab==='funds'?<DataTable rows={valid?fs:[]} columns={[{key:'name',label:'Fund'},{key:'custodian',label:'Custodian'},{key:'authorized',label:'Authorized amount',align:'right',render:f=>money(f.authorized)},{key:'balance',label:'Recorded cash as of '+dateLabel(end),align:'right',render:f=><strong>{money(db.movements.filter(m=>m.fund===f.id&&m.date<=end).reduce((n,m)=>n+m.amount,0))}</strong>},{key:'count',label:'Last physical count',render:f=>{const c=[...db.counts].filter(c=>c.fund===f.id&&c.date<=end).at(-1);return c?<>{money(c.physical)}<small>{dateLabel(c.date)} · {money(c.physical-c.recorded)} variance</small></>:'No count recorded'}}]}/>:<DataTable rows={advances} columns={[{key:'id',label:'Request',render:r=><button className="text-link" onClick={()=>navigate('/cash-requests/'+r.id)}>{r.id}</button>},{key:'owner',label:'Employee'},{key:'fund',label:'Fund',render:r=>db.funds.find(f=>f.id===r.fund)?.name},{key:'releaseDate',label:'Released',render:r=>dateLabel(r.releaseDate)},{key:'due',label:'Due',render:r=><>{dateLabel(r.due)}{r.due<TODAY&&<small className="overdue">Overdue</small>}</>},{key:'amount',label:'Released amount',align:'right',render:r=>money(r.amount)}]}/>}</div><div className="list-note"><ShieldCheck size={15}/> Mayden Group · Generated for {dateLabel(TODAY)} · All figures use session data in PHP.</div></>}

function Policies(){const {navigate,role}=useApp();return <><PageHeading title="Policies & guide" description="Know the journey, the responsibilities, and the demonstration assumptions."/><div className="guide-intro"><span><ShieldCheck size={32}/></span><div><h2>Small expenses. Clear accountability.</h2><p>Every advance connects its purpose, approval, cash handover, actual expenses, and final funding.</p></div></div><Section title="Personal expense reimbursement" description="A separate starting point when you use your own money."><div className="modal-body"><p>Expense Settlements → New Settlement → Claim personal expenses. Enter actual expenses, merchant, date and receipts, then submit for approval. Approved claims remain owed until Finance records payment.</p><p>If an unreleased Cash Request covers the same costs, open it and choose Use personal funds instead. Cancellation and reimbursement draft creation happen together. Released advances must be liquidated.</p><Btn onClick={()=>navigate('/liquidations')}>Open Expense Settlements</Btn></div></Section><Section title="From request to replenishment"><div className="journey-inline">{[['Request','Requester',Banknote],['Approve','Approver',CircleCheck],['Release','Custodian',Wallet],['Liquidate','Requester',ReceiptText],['Verify','Custodian',ShieldCheck],['Replenish','Finance',RefreshCw]].map(([name,who,Icon],i)=><React.Fragment key={name}><div><span>{i+1}</span><Icon size={23}/><strong>{name}</strong><small>{who}</small></div>{i<5&&<ChevronRight size={17}/>}</React.Fragment>)}</div></Section><div className="policies-grid"><Section title="Demonstration assumptions" description="These are sample operating rules, pending company approval."><ul className="policy-list"><li><CalendarDays size={19}/><span><strong>Liquidation in 3 calendar days</strong><p>Calculated from the actual release date; configurable per fund.</p></span></li><li><ReceiptText size={19}/><span><strong>Receipt on each actual expense</strong><p>PDF, JPG, and PNG files are available in this browser session only.</p></span></li><li><RefreshCw size={19}/><span><strong>25% remaining cash threshold</strong><p>A demonstration reference; replenishment can be requested when eligible expenses exist.</p></span></li><li><CheckCheck size={19}/><span><strong>Separate approval and funding receipt</strong><p>Approval does not move cash. Posting explicitly confirms receipt.</p></span></li><li><ShieldCheck size={19}/><span><strong>Reserved replenishment sources</strong><p>Draft and pending replenishments reserve their selected liquidations to prevent duplicates.</p></span></li></ul></Section><Section title="Prototype boundaries"><ul className="policy-list"><li><Info size={19}/><span><strong>Session-only data</strong><p>All records reset on refresh. There is no permanent storage or backend.</p></span></li><li><Users size={19}/><span><strong>Role preview</strong><p>Switching roles demonstrates responsibility; it does not provide real authentication.</p></span></li><li><FileText size={19}/><span><strong>Honest sample evidence</strong><p>Seeded receipts are explicitly marked sample documents. User-selected files remain local.</p></span></li><li><Banknote size={19}/><span><strong>No real money movement</strong><p>All releases, returns, and postings are simulated. No banking or accounting integration is connected.</p></span></li><li><Scale size={19}/><span><strong>Cash variance is retained</strong><p>Count approval preserves any shortage or overage. Corrections and reversals require future approved workflows.</p></span></li></ul></Section></div></>}
function Guide({onClose,changeRole}){const {navigate}=useApp();const steps=[['requester','Create a cash request','Add a purpose, choose a fund, and enter estimated items. Submit intentionally.','/cash-requests/new'],['approver','Review and approve','Open the For Approval queue, review the estimates, and record your decision.','/cash-requests'],['custodian','Release the cash','Open an Approved request. Confirm the actual handover with a voucher reference.','/cash-requests'],['requester','Account for actual spending','Select your released request, update copied items, attach receipts, and submit.','/liquidations/new'],['custodian','Verify and replenish','Confirm any returned cash, verify the expenses, and select liquidated records for replenishment.','/liquidations'],['finance','Approve, then post funding','Approve the replenishment, then explicitly record funding receipt. Trace the cash in the ledger.','/replenishments']];return <Modal title="Explore the complete cash journey" description="Switch roles at any point using the preview selector above." wide onClose={onClose}><div className="guide-steps">{steps.map(([role,title,text,path],i)=><button key={i} onClick={()=>{onClose();changeRole(role);setTimeout(()=>navigate(path),0)}}><span className="step-number">{i+1}</span><div><small>{names[role]}</small><h3>{title}</h3><p>{text}</p></div><ArrowUpRight size={18}/></button>)}</div><div className="modal-footer"><span className="muted">Demo date: {dateLabel(TODAY)} · PHP</span><Btn variant="primary" onClick={onClose}>Start exploring</Btn></div></Modal>}

export {useApp,Btn,Pill,Field,Notice,Section,Modal,DataTable,PageHeading,History,Summary,ExpenseEditor,ExpenseReadTable,Empty,downloadCSV,MiniStat};
